// ============================================================
// 美梦巡游·预设自动流转系统 v1.12
// 模型分页 + 预设方案快照 + API自动嗅探 + 预设切换
// 推理设置幂等检查 Ver.24
// v1.1 (2026-07-20): 切换/恢复不再报假成功——applyActivationTree
// 回读验证实际生效数,0条生效或API报错时如实提示错误并中止流程
// v1.2 (2026-07-20): UI三修——①导航标签禁折行+紧缩内边距,四标签单行
// 零截断;②面板居中改 flex+margin:auto,治iPad上半截飞出屏幕;③面板
// 标题显示版本号(每次改动必须同步升这里和标题的版本号)
// v1.2.1 (2026-07-20): 仅清理注释措辞,无功能变化; v1.3 (2026-07-21): 大总结Story_Archive编辑器窗口改vw/dvh+flex居中,修iPad上半截飞出屏幕(与v1.2主面板同根病,漏网补刀)
// v1.4 (2026-08-11): 修「大总结只发档案不发要求」——档案正文里的 | 被 STScript
// 当成命令分隔符,把 /send 从中间截断,已对内容做转义;要求为空时直接拦下不发
// (原为要求和模板都空才拦);压缩要求默认值兜底改真值判断(原来只认 undefined,
// 被手动清空成空串后永不再触发)
// v1.12 (2026-10-17): 排除参数匹配Gemini4或Argon，移除误拼别名。
// v1.10 (2026-10-17): 删除头部正则选择器及启动自动恢复；尾部名称去掉必开。
// v1.9 (2026-10-17): Gemini4Argon自动排除采样参数；移除模型尾部自动切换，普通方案保留手选尾部。
// ============================================================

(async () => {

// 版本号:改任何东西都要升它(显示在面板标题,用户靠它辨认版本)
const WX_VERSION = 'v1.12';

// ── 常量 ────────────────────────────────────────────────────
// 脚本运行在隐藏 iframe 内, JS-Slash-Runner 的 $ (jQuery) 已绑定主页面
// 重定向 document 到主页面，同时保留 parentWin 用于获取视口尺寸
const parentWin = window.parent && window.parent !== window ? window.parent : window;
const document = parentWin.document;

const SCRIPT_ID = getScriptId();
const BUTTON_NAME = '🦋梦游助手';

const MODELS = ['Claude', 'Gemini', 'DeepSeek', 'GLM'];

// 快捷指令默认数据
const DEFAULT_QUICK_COMMANDS = [
  { group: '叙事节奏', items: [
    { id: 'qc_advance', label: '推进剧情', text: '<request：推进剧情。当前场景已经充分展开，请进行时间快进或场景转换，将故事推向下一个节点。不要停留在当前场景继续描写细节。>' },
    { id: 'qc_deepen', label: '保持深挖', text: '<request：不要跳转到新的场景或事件。留在当前场景中，继续展开角色之间的互动、对话和细节。把这个场景写透。>' },
    { id: 'qc_slow', label: '慢下来', text: '<request：减少事件密度，放慢节奏。专注于感官描写、环境氛围、角色的身体感受和情绪流动。不要推进新的事件，让当前的时刻停留更久。>' },
  ]},
  { group: '场景控制', items: [
    { id: 'qc_surprise', label: '引入意外', text: '<request：在当前场景中制造一个意外事件，打断当前的节奏。可以是惊喜也可以是惊吓，可以是外部突发状况也可以是角色突然做出意料之外的举动。这个意外应该符合当前世界观的逻辑，但超出角色和用户的预期。让场景的走向因此改变。>' },
    { id: 'qc_pov', label: '切换视角', text: '<request：切换到另一个角色的视角进行叙述。展示该角色此刻的内心活动、感知和判断，让读者看到主角看不到的东西。>' },
    { id: 'qc_npc', label: '引入新角色', text: '<request：在当前场景中自然地引入一个新角色或路人。这个人的出现应该符合当前环境的逻辑，可以是偶遇、打断、或者背景中突然引起注意的存在。>' },
  ]},
  { group: '角色驱动', items: [
    { id: 'qc_proactive', label: '角色主动推进', text: '<request：让NPC主动做出行动或发起话题，而不是被动等待用户的输入。NPC有自己的意志、计划和需求，让他表现出来。>' },
    { id: 'qc_vulnerable', label: '展示脆弱面', text: '<request：让当前互动中的NPC展示脆弱的一面。可以是语气中的犹豫、不经意的暴露、肢体语言的松动、或者短暂地卸下防御。不要刻意煽情，让它自然发生。>' },
  ]},
  { group: '元指令', items: [
    { id: 'qc_critique', label: '吃我一击', text: '评审以上文本<request：请以一个严苛的文学编辑的身份，审视上方所有AI生成的回复。这些内容是另一个AI写的，你需要评估：1.角色是否渐渐OOC（偏离人设）；2.是否出现了油腻、肉麻、过度讨好用户的倾向；3.描写是否出现了套路化和重复；4.情绪表达是否真实可信。5.是否错误的理解了戏剧性，让人物行为过激或过郁。给出具体的问题定位和改进方向。之后的回复请参照你自己的分析进行修正。>' },
  ]},
];

// 模型名称关键词映射（用于API嗅探）
const MODEL_KEYWORDS = {
  Claude:   ['claude'],
  Gemini:   ['gemini'],
  DeepSeek: ['deepseek'],
  GLM:      ['glm', 'chatglm'],
};

// 压缩总结模式的默认「压缩要求」提示词（可在设置里单独编辑）
const DEFAULT_COMPRESS_REQUIRE = '[剧情档案·压缩重构协议]\n上方<Story_Archive>是已多次累积的历史归档。请把它和最新尚未归档的剧情，一次性重构为一份完整档案：\n\n1. 压缩旧档（保真优先）：\n- 必须保留：所有登场人物、核心关系流变、重大既成事实、未竟伏笔、关键承诺与道具、情感转折点。这些是记忆主干，一个都不能丢。\n- 可以精简：重复的日常细节、可归纳的流水账、冗余环境描写。\n- 合并同类章节，用 **Day X** 时间轴串联，重剧情写长，过渡一笔带过。\n\n2. 续写新章：\n- 将最新一段尚未归档的剧情，按相同结构完整总结，接在压缩后的历史之后。\n\n3. 自洽要求：\n- 最终输出一份【完整、独立】的档案，它将整体替换旧档，必须能独立承载全部历史记忆，不得依赖任何被删掉的原文。';



// ── 存储结构 ─────────────────────────────────────────────────
function loadStorage() {
  const raw = getVariables({ type: 'script', script_id: SCRIPT_ID });
  if (raw && raw.initialized) {
    if (raw.autoSwitch === undefined) raw.autoSwitch = true;
    if (!raw.globalProfileId) raw.globalProfileId = null;
    // Migration: 单个 summaryProfile → 数组 summaryProfiles
    if (raw.summaryProfile && !raw.summaryProfiles) {
      raw.summaryProfiles = [raw.summaryProfile];
      raw.activeSummaryId = raw.summaryProfile.id;
      delete raw.summaryProfile;
    }
    if (!raw.summaryProfiles) raw.summaryProfiles = [];
    if (raw.activeSummaryId === undefined) raw.activeSummaryId = null;
    if (!raw.archiveThresholdMode) raw.archiveThresholdMode = 'floor';
    // Migration: 旧的单个 archivePrompt → 拆分成 require + format
    if (raw.archivePrompt && !raw.archivePromptRequire) {
      raw.archivePromptRequire = raw.archivePrompt;
      raw.archivePromptFormat = '';
      delete raw.archivePrompt;
    }
    if (raw.archivePromptRequire === undefined) raw.archivePromptRequire = '';
    if (raw.archivePromptFormat === undefined) raw.archivePromptFormat = '';
    // 用真值判断：被手动清空存成 '' 时也要补回默认，否则兜底永不再触发。
    if (!raw.archiveCompressRequire) raw.archiveCompressRequire = DEFAULT_COMPRESS_REQUIRE;
    if (raw.lastArchiveFloor === undefined) raw.lastArchiveFloor = 0;
    if (raw.archiveAutoRemind === undefined) raw.archiveAutoRemind = true;
    if (raw.archiveKeepFloors === undefined) raw.archiveKeepFloors = 5;
    if (!raw.quickCommandEdits) raw.quickCommandEdits = {};
    if (!raw.quickCommandCustom) raw.quickCommandCustom = [];
    if (raw.customQuickCommands) {
      raw.quickCommandEdits = raw.customQuickCommands;
      delete raw.customQuickCommands;
    }
    if (!raw.theme) raw.theme = 'night';
    return raw;
  }
  return {
    initialized: true,
    activeModel: 'Claude',          // 当前激活模型分页
    models: {
      Claude:   { profiles: [], defaultId: null },
      Gemini:   { profiles: [], defaultId: null },
      DeepSeek: { profiles: [], defaultId: null },
      GLM:      { profiles: [], defaultId: null },
    },
    summaryProfiles: [],            // 大总结预设方案（多个）
    activeSummaryId: null,          // 当前激活的大总结预设ID
    archiveThresholdMode: 'floor',  // 阈值模式: 'floor' | 'token'
    archivePromptRequire: '[剧情档案馆生成协议]\n1. 聚合原则：\n- 合并同类项：忽略细分的[剧情锚点]"阶段"后缀（如"·开端"），将所有主标题相同的事件[剧情锚点]合并为单一章节块。\n- 字数不设限：根据该章节的剧情密度，弹性调整篇幅。重剧情章节可写长，过渡章节一笔带过。\n\n2. 结构规范：\n- 使用 **Day X** 作为内部时间轴的刻度（数据来源：过往楼层的[时空坐标]）。\n- 必须记录地点流变和关系流变。',
    archivePromptFormat: '[档案说明]: 本区域存储 L0-XX 的核心剧情概要，拥有极高的叙事背景权重。\n\n📌 卷宗：[[ 章节主标题 ]]\n【时空流变】:\n   Day {X} ({地点}) -> Day {Y} ({地点})\n【事件脉络】:\n   (Day {X}) ...\n   (Day {Y}) ...\n【高光金句】:\n   > {Char}: "..." (Day {X})\n【关系快照 (章节完结时)】:\n   [状态定格]: ...\n   [情感沉淀]: ...\n\n📌 卷宗：[[ 下一章节 ]]\n...\n\n---\n[档案封存戳]\n截止存档时关系: ...\n注意: 此为过往历史。当前最新互动请以最高楼层的几楼中的**叙事矩阵**为准。',
    archiveCompressRequire: DEFAULT_COMPRESS_REQUIRE,  // 压缩模式的压缩要求
    archiveToken:   80000,
    archiveFloor:   100,
    lastArchiveFloor: 0,       // 上次归档时的楼层数（用于"每N楼"触发）
    archiveKeepFloors: 5,      // 归档后保留最近N层，其余隐藏
    archiveAutoRemind: true,   // 自动总结提醒开关
    autoSwitch: true,          // API自动切换开关
    globalProfileId: null,     // 关闭自动切换时的全局默认预设方案
    quickCommandEdits: {},     // 用户编辑过的快捷指令内容 { id: text }
    quickCommandCustom: [],    // 用户自定义的快捷指令 [{ id, label, text, group }]
    theme: 'night',            // 主题: 'night' | 'day'
  };
}

function saveStorage(data) {
  replaceVariables(data, { type: 'script', script_id: SCRIPT_ID });
}

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// ── 激活树读取 ───────────────────────────────────────────────
const API_PARAM_KEYS = ['temperature', 'frequency_penalty', 'presence_penalty', 'top_p', 'top_k', 'min_p', 'repetition_penalty', 'openai_max_tokens'];
const API_SLIDER_MAP = {
  temperature: '#temp_openai',
  frequency_penalty: '#freq_pen_openai',
  presence_penalty: '#pres_pen_openai',
  top_p: '#top_p_openai',
  top_k: '#top_k_openai',
  min_p: '#min_p_openai',
  repetition_penalty: '#repetition_penalty_openai',
  openai_max_tokens: '#openai_max_tokens',
};

function captureActivationTree() {
  try {
    const preset = getPreset('in_use');
    return (preset.prompts || []).map(p => ({ id: p.id, enabled: !!p.enabled }));
  } catch(e) {
    console.warn('[美梦重现预设流转] 读取激活树失败', e);
    return [];
  }
}

function captureApiParams() {
  try {
    const params = {};
    Object.entries(API_SLIDER_MAP).forEach(([k, sel]) => {
      const v = $(sel).val();
      if (v !== undefined && v !== '') params[k] = Number(v);
    });
    return params;
  } catch(e) {
    console.warn('[美梦重现预设流转] 读取API参数失败', e);
    return {};
  }
}

async function applyActivationTree(tree, { restoreTail = false } = {}) {
  // 返回 { matched, verified, total }：matched=方案条目在当前预设里找到几个,
  // verified=写入后回读确认真的生效了几个。API 异常直接往上抛,由调用方报错,
  // 不再吞掉错误(v1.1修复:以前这里静默失败,外面照样弹"已切换"的假成功提示)
  if (!tree || !tree.length) return { matched: 0, verified: 0, total: 0 };
  const map = {};
  // 普通方案保留四条模型尾部的手选状态；归档及快照恢复仍完整执行。
  const manageTail = restoreTail || !!archiveState;
  tree.forEach(t => {
    if (!manageTail && MODEL_TAIL_IDS.has(t.id)) return;
    map[t.id] = t.enabled;
  });
  // 新拆分的思考模块：归档无主思考时不留孤立闭合，旧方案也能自动配齐收束。
  const cotMainIds = ['eb0228e2-a38b-46ed-8470-cca127cb64a5', 'c8b085cf-1dee-4524-9104-ec0e26c3c88c', 'a6b9d029-79b1-4d60-af02-646ec1088947'];
  const currentPrompts = getPreset('in_use').prompts || [];
  const hasMain = currentPrompts.some(p => cotMainIds.includes(p.id) && (p.id in map ? map[p.id] : p.enabled));
  if (currentPrompts.some(p => p.id === 'wx-cot-output-close')) map['wx-cot-output-close'] = hasMain;
  if (!hasMain && currentPrompts.some(p => p.id === 'wx-cot-rhetoric')) map['wx-cot-rhetoric'] = false;
  let matched = 0;
  await updatePresetWith('in_use', preset => {
    preset.prompts = (preset.prompts || []).map(p => {
      if (p.id in map) { matched++; return { ...p, enabled: map[p.id] }; }
      return p;
    });
    return preset;
  }, { render: 'debounced' });
  // 回读验证:确认开关真的落到了预设上
  let verified = 0;
  const now = getPreset('in_use');
  (now.prompts || []).forEach(p => {
    if (p.id in map && !!p.enabled === !!map[p.id]) verified++;
  });
  return { matched, verified, total: Object.keys(map).length };
}

// 统一的切换结果汇报:真成功才报成功,失败说清楚原因。返回是否算成功。
function reportApply(res, okMsg) {
  if (!res || res.total === 0) {
    toastr.warning('[美梦巡游] 这个方案是空的，没有可应用的条目');
    return false;
  }
  if (res.matched === 0) {
    toastr.error(`[美梦巡游] 切换失败：方案里的 ${res.total} 个条目在当前预设里一个都没找到。预设可能换过或条目重建过，请在当前预设下重新保存一次方案`);
    return false;
  }
  if (res.verified < res.matched) {
    toastr.error(`[美梦巡游] 切换没有完全生效（写入 ${res.matched} 个，回读只确认 ${res.verified} 个），当前酒馆助手版本可能不兼容，请截图反馈`);
    return false;
  }
  if (res.matched < res.total) {
    toastr.warning(okMsg + `（提示：有 ${res.total - res.matched} 个条目没匹配上，预设可能更新过，建议重新保存方案）`);
    return true;
  }
  toastr.success(okMsg);
  return true;
}

async function applyApiParams(params) {
  if (!params || !Object.keys(params).length) return;
  try {
    Object.entries(API_SLIDER_MAP).forEach(([k, sel]) => {
      if (params[k] !== undefined) {
        $(sel).val(params[k]).trigger('input');
      }
    });
  } catch(e) {
    console.warn('[美梦重现预设流转] 应用API参数失败', e);
  }
}




// ── 「以…开始回复」按模型记忆(2026-08-20) ──────────────────
// GLM/DS 是否需要填 <think> 因渠道而异,没法硬编码;做成记忆式:
// 离开某模型时记住当前手调状态,切回来时自动恢复。
// 3.7 Flash 例外:必须为空,切过去强制清空(强制态不记忆)。
// 页面刚加载时只登记不恢复,避免覆盖刷新前的手调。
// ── 主页面访问工具(脚本跑在隐藏 iframe 里,$ 只能看到 iframe 内的空 DOM) ──
function mjq() {
  try {
    if (typeof window.parent !== 'undefined' && window.parent !== window && window.parent.jQuery) {
      return window.parent.jQuery;
    }
  } catch(e) {}
  return $;
}
function mctx() {
  const ST = (typeof SillyTavern !== 'undefined') ? SillyTavern
    : (window.parent && window.parent.SillyTavern) ? window.parent.SillyTavern : null;
  return ST ? ST.getContext() : null;
}

const FORCE_EMPTY_BIAS = ['Gemini37Or38Flash', 'Claude'];
let lastBiasModelKey = null;
function applyStartReplyMemory(modelName, startup) {
  try {
    const ctx = mctx();
    const pu = ctx && ctx.powerUserSettings;
    if (!pu) return;
    const jq = mjq();
    const getBias = () => String(pu.user_prompt_bias || '');
    const getShow = () => !!pu.show_user_prompt_bias;
    const setBias = (v, show) => {
      pu.user_prompt_bias = v;
      pu.show_user_prompt_bias = !!show;
      jq('#start_reply_with').val(v);
      jq('#chat-show-reply-prefix-checkbox').prop('checked', !!show);
      if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
    };
    const lower = String(modelName || '').toLowerCase();
    if (!lower) return;
    const family = detectModel(lower) || '其他';
    const key = isRestrictedFlash(lower) ? 'Gemini37Or38Flash' : family;
    if (key === lastBiasModelKey) return;
    const storage = loadStorage();
    storage.startReplyByModel = storage.startReplyByModel || {};
    // 离开旧模型:记住手调状态(强制态不记)
    if (lastBiasModelKey && !FORCE_EMPTY_BIAS.includes(lastBiasModelKey)) {
      storage.startReplyByModel[lastBiasModelKey] = { bias: getBias(), show: getShow() };
    }
    if (FORCE_EMPTY_BIAS.includes(key)) {
      // 3.7f 填了必报错;Claude(反重力等渠道)不接受 assistant 预填充,请求须以 user 结尾
      if (getBias() !== '' || getShow()) {
        setBias('', false);
        toastr.info('[美梦巡游] ' + key + ':「以…开始回复」已强制清空');
      }
    } else if (!startup) {
      // 不给任何模型预设默认值:开标签由尾部铁律负责,填了会重复。
      // 你手动调过的设置仍然会被记住并恢复。
      const saved = storage.startReplyByModel[key];
      if (saved) {
        setBias(saved.bias, saved.show);
        if (saved.bias) toastr.info('[美梦巡游] ' + key + ':「以…开始回复」=' + saved.bias);
      }
    } // 尊重当前手调
    lastBiasModelKey = key;
    saveStorage(storage);
  } catch(e) { console.warn('[美梦巡游] 回复前缀记忆失败', e); }
}

// ── 附加参数随模型自动切换(2026-08-20) ──────────────────────
// 3.7f 不许自定义采样参数,DS 要关 thinking;换模型时自动改写
// 「包括/排除主体参数」,其余模型清空恢复默认。
function isRestrictedFlash(modelName) {
  const m = String(modelName || '').toLowerCase();
  return /3[.-][78]/.test(m) && m.includes('flash');
}
function isGemini4Argon(modelName) {
  return /gemini[\s._-]*4|argon/i.test(String(modelName || ''));
}
const BODY_PARAM_RULES = [
  { test: isGemini4Argon,
    include: '',
    exclude: '- presence_penalty\n- frequency_penalty\n- top_p\n- top_k\n- temperature',
    label: 'Gemini4Argon:排除采样参数' },
  { test: isRestrictedFlash,
    include: '',
    exclude: '- presence_penalty\n- frequency_penalty\n- top_p\n- top_k\n- temperature',
    label: 'Gemini 3.7 / 3.8 Flash:排除采样参数' },
  { test: m => m.includes('deepseek'),
    include: '{"thinking": {"type": "disabled"}}',
    exclude: '',
    label: 'DeepSeek:关闭thinking' },
];
function applyModelBodyParams(modelName) {
  try {
    const ctx = mctx();
    const oai = ctx && ctx.chatCompletionSettings;
    if (!oai) return;
    const jq = mjq();
    const lower = String(modelName || currentModelName()).toLowerCase();
    if (!lower) return;
    const rule = BODY_PARAM_RULES.find(r => r.test(lower));
    const inc = rule ? rule.include : '';
    const exc = rule ? rule.exclude : '';
    // 续写预填充/请求思维链:3.7flash 必须全关,其他模型恢复勾选(旧常态)
    const flash37 = isRestrictedFlash(lower);
    const isClaude = lower.includes('claude');
    // 续写预填充会以 assistant 身份发最后一条:3.7f 会干等超时,Claude 直接 400
    const wantContinue = !(flash37 || isClaude);
    const wantThoughts = !flash37;
    if (!!oai.continue_prefill !== wantContinue) {
      oai.continue_prefill = wantContinue;
      jq('#continue_prefill').prop('checked', wantContinue);
    }
    if (!!oai.show_thoughts !== wantThoughts) {
      oai.show_thoughts = wantThoughts;
      jq('#openai_show_thoughts').prop('checked', wantThoughts);
    }
    // 助手预填充恒为空:开标签由尾部【开幕铁律】负责,预填充会造成 <parade> 重复
    const prefill = '';
    const prefillChanged = oai.assistant_prefill !== prefill;
    if (prefillChanged) {
      oai.assistant_prefill = prefill;
      jq('#claude_assistant_prefill').val(prefill);
    }
    if (!prefillChanged && oai.custom_include_body === inc && oai.custom_exclude_body === exc) return;
    oai.custom_include_body = inc;
    oai.custom_exclude_body = exc;
    // 附加参数弹窗若开着,同步显示
    jq('#custom_include_body').val(inc);
    jq('#custom_exclude_body').val(exc);
    if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
    toastr.info('[美梦巡游] 附加参数已随模型调整:' + (rule ? rule.label : '已清空,恢复默认采样参数'));
  } catch(e) { console.warn('[美梦巡游] 附加参数自动切换失败', e); }
}

// ── 模型检测 ─────────────────────────────────────────────────
// 普通方案不改模型尾部；这些条目由用户手动选择。
const MODEL_TAIL_IDS = new Set(['wx-tail-gemini-pro', 'wx-tail-gemini-glm',
  'wx-tail-ds-official', 'mmag71wq4a4zxz2grfy']);

function currentModelName() {
  try {
    const ctx = mctx();
    const oai = ctx && ctx.chatCompletionSettings;
    if (typeof ctx?.getChatCompletionModel === 'function') {
      return ctx.getChatCompletionModel(oai) || '';
    }
    if (!oai) return '';
    // 兼容没有暴露模型读取方法的旧版酒馆，按实际API来源读取。
    const sourceKeys = { makersuite: 'google_model', vertexai: 'vertexai_model',
      custom: 'custom_model', claude: 'claude_model', openai: 'openai_model',
      openrouter: 'openrouter_model', deepseek: 'deepseek_model' };
    const key = sourceKeys[oai.chat_completion_source];
    return key ? (oai[key] || '') : '';
  } catch(e) { return ''; }
}

function detectModel(modelName) {
  const lower = (modelName || '').toLowerCase();
  for (const [model, keywords] of Object.entries(MODEL_KEYWORDS)) {
    if (keywords.some(k => lower.includes(k))) return model;
  }
  return null;
}

async function autoSwitchByModel(modelName) {
  // 归档流程进行中时跳过自动切换，避免覆盖大总结预设或快照恢复
  if (archiveState) return;
  const storage = loadStorage();
  if (!storage.autoSwitch) return;
  const detected = detectModel(modelName);
  if (!detected) return;
  const modelData = storage.models[detected];
  if (!modelData || !modelData.defaultId) return;
  const profile = modelData.profiles.find(p => p.id === modelData.defaultId);
  if (!profile) return;
  try {
    const res = await applyActivationTree(profile.tree);
    await applyApiParams(profile.apiParams);
    reportApply(res, `[美梦巡游] 已自动切换至 ${detected} · ${profile.name}`);
  } catch(e) {
    console.error('[美梦巡游] 自动切换失败', e);
    toastr.error('[美梦巡游] 自动切换失败：' + e.message);
  }
}

// 手动一键切换到某模型的默认预设方案（不受"随API切换"开关影响）
async function switchToModelDefault(model) {
  const storage = loadStorage();
  const modelData = storage.models[model];
  if (!modelData || !modelData.defaultId) {
    toastr.warning(`[美梦巡游] ${model} 还没有设置默认预设方案，先去"预设切换配置"页设置一个吧`);
    return;
  }
  const profile = modelData.profiles.find(p => p.id === modelData.defaultId);
  if (!profile) {
    toastr.warning(`[美梦巡游] ${model} 的默认方案不存在了，请重新设置`);
    return;
  }
  try {
    const res = await applyActivationTree(profile.tree);
    await applyApiParams(profile.apiParams);
    reportApply(res, `[美梦巡游] 已切换至 ${model} · ${profile.name}`);
  } catch(e) {
    console.error('[美梦巡游] 切换失败', e);
    toastr.error('[美梦巡游] 切换失败：' + e.message);
  }
}

