// ── UI 渲染 ──────────────────────────────────────────────────
let panelEl = null;
let currentTab = null;    // 当前分页
let editingId = null;     // 当前编辑的预设方案id（null=新建）
let editingTarget = null; // 'profile' | 'summary'

function injectStyle() {
  if ($('#wx-style').length) return;
  $('<style>').attr('id', 'wx-style').html(CSS).appendTo('head');
}

// 元数据展示文字
function profileMeta(profile) {
  const tree = profile.tree || [];
  const enabled = tree.filter(t => t.enabled).length;
  const parts = [];
  if (enabled > 0) parts.push(enabled + '条目');
  const ap = profile.apiParams;
  if (ap) {
    if (ap.temperature !== undefined) parts.push('T:' + ap.temperature);
    if (ap.frequency_penalty) parts.push('F:' + ap.frequency_penalty);
    if (ap.presence_penalty) parts.push('P:' + ap.presence_penalty);
  }
  return parts.length > 0 ? parts.join(' | ') : '未配置';
}

// ── 编辑面板 ─────────────────────────────────────────────────
function buildEditPanel(existingProfile, isSummary, storage, modelKey) {
  const p = existingProfile || {
    id: null, name: '',
    tree: [],
  };
  const isEdit = !!existingProfile;

  const div = document.createElement('div');
  div.className = 'wx-sub-panel';

  div.innerHTML = `
    <div class="wx-sub-title">
      ${isEdit ? '✏️ 编辑预设方案' : '➕ 新建预设方案'}
    </div>

    <div class="wx-form-row">
      <label class="wx-label">配置名称</label>
      <input class="wx-input" id="wx-ep-name" placeholder="例：古风剧情常用" value="${escHtml(p.name)}">
    </div>


    <div class="wx-footer" style="padding: 10px 0 0; border-top: none;">
      <button class="wx-btn" id="wx-ep-cancel">取消</button>
      <button class="wx-btn wx-btn-primary" id="wx-ep-save">
        ${isEdit ? '更新（重读激活树）' : '完成（读取激活树）'}
      </button>
    </div>
  `;


  // 取消
  div.querySelector('#wx-ep-cancel').addEventListener('click', () => {
    editingId = null;
    editingTarget = null;
    renderBody(storage);
  });

  // 保存/更新
  div.querySelector('#wx-ep-save').addEventListener('click', async () => {
    const name = div.querySelector('#wx-ep-name').value.trim();
    if (!name) { toastr.warning('请填写配置名称'); return; }




    if (isEdit) {
      // 编辑时弹确认框
      const ok = confirm(`将重新读取当前ST激活树并覆盖原配置「${existingProfile.name}」，确认？`);
      if (!ok) return;
    }

    const tree = captureActivationTree();
    const apiParams = captureApiParams();
    const profile = {
      id:   p.id || genId(),
      name, tree, apiParams,
      updatedAt: Date.now(),
    };

    if (isSummary) {
      if (!storage.summaryProfiles) storage.summaryProfiles = [];
      if (isEdit) {
        const idx = storage.summaryProfiles.findIndex(x => x.id === profile.id);
        if (idx >= 0) storage.summaryProfiles[idx] = profile;
        else storage.summaryProfiles.push(profile);
      } else {
        storage.summaryProfiles.push(profile);
      }
      storage.activeSummaryId = profile.id;
    } else {
      const md = storage.models[modelKey];
      if (isEdit) {
        const idx = md.profiles.findIndex(x => x.id === profile.id);
        if (idx >= 0) md.profiles[idx] = profile;
        else md.profiles.push(profile);
      } else {
        md.profiles.push(profile);
      }
    }

    saveStorage(storage);
    editingId = null;
    editingTarget = null;
    renderBody(storage);
    toastr.success(isEdit ? '已更新预设方案' : '已创建预设方案');
  });

  return div;
}

// ── 自定义弹窗（替代浏览器原生 prompt） ──────────────────────────
function showInputDialog(title, placeholder, initial) {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.className = 'wx-dialog-overlay';
    overlay.innerHTML = `
      <div class="wx-dialog">
        <div class="wx-dialog-title">🌙 ${escHtml(title)}</div>
        <input type="text" placeholder="${escHtml(placeholder || '')}">
        <div class="wx-dialog-actions">
          <button class="wx-dialog-cancel">取消</button>
          <button class="wx-dialog-ok">确定</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const input = overlay.querySelector('input');
    if (initial) { input.value = initial; input.select(); }
    input.focus();
    const close = (val) => { $(overlay).remove(); resolve(val); };
    overlay.querySelector('.wx-dialog-cancel').addEventListener('click', () => close(null));
    overlay.querySelector('.wx-dialog-ok').addEventListener('click', () => close(input.value));
    input.addEventListener('keydown', e => {
      if (e.key === 'Enter') close(input.value);
      if (e.key === 'Escape') close(null);
    });
    overlay.addEventListener('click', e => { if (e.target === overlay) close(null); });
  });
}

// ── 快捷指令页 ─────────────────────────────────────────────────
function getAllCommands(storage) {
  const edits = storage.quickCommandEdits || {};
  const customs = storage.quickCommandCustom || [];
  const groups = DEFAULT_QUICK_COMMANDS.map(g => ({
    group: g.group,
    items: [
      ...g.items.map(cmd => ({
        id: cmd.id,
        label: edits[cmd.id + '_label'] || cmd.label,
        text: edits[cmd.id] !== undefined ? edits[cmd.id] : cmd.text,
        builtIn: true,
      })),
      ...customs.filter(c => c.group === g.group).map(c => ({
        id: c.id, label: c.label,
        text: edits[c.id] !== undefined ? edits[c.id] : c.text,
        builtIn: false,
      })),
    ],
  }));
  return groups;
}

function renderQuickCommands(body, storage) {
  const groups = getAllCommands(storage);

  // ── 一键切默认预设（置顶，与其他按钮分隔） ──
  const pjSec = document.createElement('div');
  pjSec.className = 'wx-qc-group wx-preset-jump';
  const pjHeader = document.createElement('div');
  pjHeader.className = 'wx-qc-group-header';
  pjHeader.innerHTML = '<span class="wx-qc-group-title">点击切换到默认预设</span>';
  pjSec.appendChild(pjHeader);
  const pjList = document.createElement('div');
  pjList.className = 'wx-qc-list';
  [
    { label: 'Claude', model: 'Claude', cls: 'wx-pj-claude' },
    { label: 'Gemini', model: 'Gemini', cls: 'wx-pj-gemini' },
    { label: 'GLM',    model: 'GLM',    cls: 'wx-pj-glm' },
    { label: 'DS',     model: 'DeepSeek', cls: 'wx-pj-ds' },
  ].forEach(({ label, model, cls }) => {
    const b = document.createElement('button');
    b.className = 'wx-qc-btn wx-pj-btn ' + cls;
    b.textContent = label;
    b.addEventListener('click', () => switchToModelDefault(model));
    pjList.appendChild(b);
  });
  pjSec.appendChild(pjList);
  body.appendChild(pjSec);

  groups.forEach(group => {
    const sec = document.createElement('div');
    sec.className = 'wx-qc-group';

    const header = document.createElement('div');
    header.className = 'wx-qc-group-header';
    header.innerHTML = '<span class="wx-qc-group-title">' + escHtml(group.group) + '</span>';

    const addBtn = document.createElement('button');
    addBtn.className = 'wx-qc-add-btn';
    addBtn.textContent = '+';
    addBtn.title = '添加自定义指令';
    addBtn.addEventListener('click', async () => {
      const name = await showInputDialog('新建快捷指令 — ' + group.group, '按钮名称');
      if (!name || !name.trim()) return;
      if (!storage.quickCommandCustom) storage.quickCommandCustom = [];
      storage.quickCommandCustom.push({
        id: 'qc_user_' + Date.now(),
        label: name.trim(),
        text: '<request：在此填写指令内容>',
        group: group.group,
      });
      saveStorage(storage);
      renderBody(storage);
    });
    header.appendChild(addBtn);
    sec.appendChild(header);

    const list = document.createElement('div');
    list.className = 'wx-qc-list';

    group.items.forEach(cmd => {
      const btn = document.createElement('button');
      btn.className = 'wx-qc-btn';
      btn.textContent = cmd.label;
      btn.addEventListener('click', () => {
        const edits = storage.quickCommandEdits || {};
        const txt = edits[cmd.id] !== undefined ? edits[cmd.id] : cmd.text;
        const ta = document.getElementById('send_textarea');
        if (ta) {
          ta.value += txt;
          ta.dispatchEvent(new Event('input', { bubbles: true }));
          ta.focus();
          hidePanel();
        }
      });
      list.appendChild(btn);
    });

    sec.appendChild(list);
    body.appendChild(sec);
  });

  // ── 一键大总结（不可编辑不可删除） ──
  const archiveSec = document.createElement('div');
  archiveSec.className = 'wx-qc-group';
  const archiveHeader = document.createElement('div');
  archiveHeader.className = 'wx-qc-group-header';
  archiveHeader.innerHTML = '<span class="wx-qc-group-title">归档工具</span>';
  archiveSec.appendChild(archiveHeader);

  const archiveBtn = document.createElement('button');
  archiveBtn.className = 'wx-qc-btn';
  archiveBtn.style.cssText = 'background:linear-gradient(135deg,rgba(168,85,247,.15),rgba(120,119,198,.15));border-color:rgba(168,85,247,.3);font-weight:600;';
  archiveBtn.textContent = '📜 一键大总结';
  archiveBtn.addEventListener('click', async () => {
    hidePanel();
    const s = loadStorage();
    await startArchiveFlow(s);
  });
  archiveSec.appendChild(archiveBtn);

  // 捕捉总结入世界书（和设置页「手动捕捉(兜底)」是同一功能）
  const captureBtn = document.createElement('button');
  captureBtn.className = 'wx-qc-btn';
  captureBtn.style.cssText = 'background:linear-gradient(135deg,rgba(72,187,120,.14),rgba(56,161,105,.14));border-color:rgba(72,187,120,.3);font-weight:600;';
  captureBtn.textContent = '📦 捕捉总结入世界书';
  captureBtn.addEventListener('click', async () => {
    hidePanel();
    await manualCaptureArchive(null);
  });
  archiveSec.appendChild(captureBtn);

  body.appendChild(archiveSec);

  // ── 楼层管理 ──
  const floorSec = document.createElement('div');
  floorSec.className = 'wx-qc-group';
  const floorHeader = document.createElement('div');
  floorHeader.className = 'wx-qc-group-header';
  floorHeader.innerHTML = '<span class="wx-qc-group-title">楼层管理</span>';
  floorSec.appendChild(floorHeader);

  const hideRow = document.createElement('div');
  hideRow.className = 'wx-qc-floor-row';
  hideRow.innerHTML = `
    <button class="wx-qc-floor-btn" id="wx-hide-floors">🙈 隐藏楼层</button>
    <button class="wx-qc-floor-btn" id="wx-unhide-floors">👁️ 取消隐藏</button>
  `;
  floorSec.appendChild(hideRow);

  floorSec.querySelector('#wx-hide-floors').addEventListener('click', async () => {
    hidePanel(); // 先关闭助手面板，方便用户拖动聊天记录查看楼层
    const input = await showInputDialog('隐藏楼层', '起始楼-结束楼，如 1-50');
    if (!input) return;
    const m = input.match(/(\d+)\s*[-~到]\s*(\d+)/);
    if (!m) { toastr.warning('格式不正确，请输入如 1-50'); return; }
    await hideFloors(parseInt(m[1]), parseInt(m[2]), true);
    toastr.success('已隐藏 ' + m[1] + '-' + m[2] + ' 楼');
  });

  floorSec.querySelector('#wx-unhide-floors').addEventListener('click', async () => {
    hidePanel(); // 先关闭助手面板
    const input = await showInputDialog('取消隐藏楼层', '起始楼-结束楼，如 1-50');
    if (!input) return;
    const m = input.match(/(\d+)\s*[-~到]\s*(\d+)/);
    if (!m) { toastr.warning('格式不正确，请输入如 1-50'); return; }
    await hideFloors(parseInt(m[1]), parseInt(m[2]), false);
    toastr.success('已取消隐藏 ' + m[1] + '-' + m[2] + ' 楼');
  });

  body.appendChild(floorSec);

  // ── 编辑指令（折叠区） ──
  const editorToggle = document.createElement('button');
  editorToggle.className = 'wx-qc-editor-toggle';
  editorToggle.innerHTML = '📝 编辑指令内容 ▾';

  const editorPanel = document.createElement('div');
  editorPanel.className = 'wx-qc-editor';

  editorToggle.addEventListener('click', () => {
    editorPanel.classList.toggle('wx-open');
    editorToggle.innerHTML = editorPanel.classList.contains('wx-open')
      ? '📝 编辑指令内容 ▴' : '📝 编辑指令内容 ▾';
  });

  groups.forEach(group => {
    const gDiv = document.createElement('div');
    gDiv.className = 'wx-qc-editor-group';
    gDiv.innerHTML = '<div class="wx-qc-editor-label">' + escHtml(group.group) + '</div>';

    group.items.forEach(cmd => {
      const item = document.createElement('div');
      item.className = 'wx-qc-editor-item';

      const hdr = document.createElement('div');
      hdr.className = 'wx-qc-editor-item-header';

      const nameInput = document.createElement('input');
      nameInput.className = 'wx-qc-editor-item-name-input';
      nameInput.value = cmd.label;
      nameInput.style.cssText = 'background:transparent;border:1px solid transparent;border-radius:4px;color:var(--wx-text,#e0e2ea);font-size:14px;font-weight:500;padding:3px 6px;width:140px;outline:none;';
      nameInput.addEventListener('focus', () => { nameInput.style.borderColor = 'var(--wx-accent,#7db5f0)'; });
      nameInput.addEventListener('blur', () => { nameInput.style.borderColor = 'transparent'; });
      nameInput.addEventListener('change', () => {
        const newName = nameInput.value.trim();
        if (!newName) return;
        if (cmd.builtIn) {
          if (!storage.quickCommandEdits) storage.quickCommandEdits = {};
          storage.quickCommandEdits[cmd.id + '_label'] = newName;
        } else {
          const c = (storage.quickCommandCustom || []).find(c => c.id === cmd.id);
          if (c) c.label = newName;
        }
        saveStorage(storage);
      });
      hdr.appendChild(nameInput);

      if (!cmd.builtIn) {
        const del = document.createElement('button');
        del.className = 'wx-qc-editor-item-del';
        del.textContent = '✕ 删除';
        del.addEventListener('click', () => {
          if (!confirm('确认删除「' + cmd.label + '」？')) return;
          storage.quickCommandCustom = (storage.quickCommandCustom || []).filter(c => c.id !== cmd.id);
          if (storage.quickCommandEdits) delete storage.quickCommandEdits[cmd.id];
          saveStorage(storage);
          renderBody(storage);
        });
        hdr.appendChild(del);
      }

      const ta = document.createElement('textarea');
      ta.value = cmd.text;

      const saveRow = document.createElement('div');
      saveRow.style.cssText = 'display:flex;justify-content:flex-end;margin-top:3px;';
      const saveBtn = document.createElement('button');
      saveBtn.textContent = '💾 保存';
      saveBtn.style.cssText = 'padding:4px 12px;font-size:13px;border:1px solid var(--wx-border,rgba(140,130,200,.2));background:var(--wx-bg2,rgba(130,120,200,.08));color:var(--wx-accent,#a78bfa);border-radius:4px;cursor:pointer;';
      const saveTip = document.createElement('span');
      saveTip.style.cssText = 'font-size:13px;color:var(--wx-accent,#a78bfa);opacity:0;transition:opacity .3s;margin-right:6px;line-height:24px;';
      saveTip.textContent = '✓ 已保存';

      const doSave = () => {
        if (!storage.quickCommandEdits) storage.quickCommandEdits = {};
        storage.quickCommandEdits[cmd.id] = ta.value;
        saveStorage(storage);
        saveTip.style.opacity = '1';
        setTimeout(() => { saveTip.style.opacity = '0'; }, 1500);
      };
      saveBtn.addEventListener('click', doSave);
      ta.addEventListener('change', doSave);

      saveRow.appendChild(saveTip);
      saveRow.appendChild(saveBtn);
      item.appendChild(hdr);
      item.appendChild(ta);
      item.appendChild(saveRow);
      gDiv.appendChild(item);
    });

    editorPanel.appendChild(gDiv);
  });

  body.appendChild(editorToggle);
  body.appendChild(editorPanel);
}

// ── 楼层隐藏/取消隐藏（使用酒馆原生 /hide /unhide 命令） ────────
async function hideFloors(from, to, hide) {
  try {
    await triggerSlash((hide ? '/hide ' : '/unhide ') + from + '-' + to);
  } catch(e) {
    console.warn('[美梦助手] hide/unhide failed', e);
  }
}

// ── 主体渲染 ─────────────────────────────────────────────────
function renderBody(storage) {
  const body = document.getElementById('wx-body');
  if (!body) return;
  body.innerHTML = '';

  document.querySelectorAll('.wx-tab').forEach(t => {
    t.classList.toggle('wx-active', t.dataset.tab === currentTab);
  });

  if (currentTab === 'quick') {
    renderQuickCommands(body, storage);
    return;
  }

  if (currentTab === 'settings') {
    renderSettings(body, storage);
    return;
  }

  if (currentTab === 'config') {
    renderConfigTab(body, storage);
    return;
  }

  if (currentTab === 'io') {
    renderIOTab(body, storage);
    return;
  }
}

// ── 预设切换配置页 ──────────────────────────────────────────
function renderConfigTab(body, storage) {
  // 自动切换开关
  const switchDiv = document.createElement('div');
  switchDiv.className = 'wx-auto-switch';
  switchDiv.innerHTML = `
    <label>开/关 根据API自动切换预设配置</label>
    <button class="wx-toggle ${storage.autoSwitch ? 'wx-on' : ''}" id="wx-auto-toggle"></button>
  `;
  switchDiv.querySelector('#wx-auto-toggle').addEventListener('click', (e) => {
    storage.autoSwitch = !storage.autoSwitch;
    if (!storage.autoSwitch && !storage.globalProfileId) {
      toastr.info('请点击 🌐 选择一个全局默认预设方案');
    }
    saveStorage(storage);
    renderBody(storage);
  });
  body.appendChild(switchDiv);


  // 图例
  const legendDiv = document.createElement('div');
  legendDiv.className = 'wx-legend';
  legendDiv.innerHTML = '⭐默认 ✅应用 ✏️重命名 🔄重置条目 ❌删除';
  body.appendChild(legendDiv);

  // ── 全局预设状态显示 ──
  if (!storage.autoSwitch) {
    const globalDiv = document.createElement('div');
    globalDiv.className = 'wx-global-status';
    let globalName = null;
    if (storage.globalProfileId) {
      for (const mk of MODELS) {
        const found = (storage.models[mk]?.profiles || []).find(p => p.id === storage.globalProfileId);
        if (found) { globalName = found.name; break; }
      }
    }
    globalDiv.innerHTML = globalName
      ? `<span style="color:var(--wx-text,#e0e2ea);">🌐 全局预设：</span><span style="color:var(--wx-accent,#a78bfa);font-weight:600;">${escHtml(globalName)}</span>`
      : `<span style="color:#e8a04a;">⚠️ 还未选择全局预设，请点击方案旁的 🌐 设置</span>`;
    body.appendChild(globalDiv);
  }

  // 四个模型竖排
  const expandedModels = window.__wxExpandedModels || {};

  MODELS.forEach(modelKey => {
    const md = storage.models[modelKey];
    if (!md) return;

    const defaultProfile = md.profiles.find(p => p.id === md.defaultId);
    const section = document.createElement('div');
    section.className = 'wx-model-section';

    const isExpanded = !!expandedModels[modelKey];

    // Header: model name + star if has default + arrow
    section.innerHTML = `
      <div class="wx-model-header" data-model="${modelKey}">
        <div class="wx-model-header-left">
          <span>${modelKey}</span>
          ${defaultProfile ? `<span class="wx-model-header-star">⭐ ${escHtml(defaultProfile.name)}</span>` : '<span style="font-size:.74em;color:var(--wx-text2,#9590b0);">未设默认</span>'}
        </div>
        <span class="wx-model-header-arrow ${isExpanded ? 'wx-expanded' : ''}">▶</span>
      </div>
      <div class="wx-model-body ${isExpanded ? 'wx-show' : ''}"></div>
    `;

    // Toggle expand
    section.querySelector('.wx-model-header').addEventListener('click', () => {
      if (!window.__wxExpandedModels) window.__wxExpandedModels = {};
      window.__wxExpandedModels[modelKey] = !window.__wxExpandedModels[modelKey];
      renderBody(storage);
    });

    // Build body content
    const mbody = section.querySelector('.wx-model-body');

    // Toolbar
    const toolbar = document.createElement('div');
    toolbar.className = 'wx-toolbar';
    toolbar.innerHTML = `
      <div class="wx-toolbar-left">
        <button class="wx-btn wx-btn-primary" data-action="new-profile">➕ 新建预设方案</button>
      </div>
    `;
    toolbar.querySelector('[data-action="new-profile"]').addEventListener('click', (e) => {
      e.stopPropagation();
      editingId = '__new__';
      editingTarget = 'profile';
      currentEditModel = modelKey;
      if (!window.__wxExpandedModels) window.__wxExpandedModels = {};
      window.__wxExpandedModels[modelKey] = true;
      renderBody(storage);
    });
    mbody.appendChild(toolbar);

    // Profile list
    const list = document.createElement('div');
    list.className = 'wx-profile-list';

    if (md.profiles.length === 0 && !(editingId === '__new__' && currentEditModel === modelKey)) {
      list.innerHTML = '<div class="wx-empty">暂无预设方案</div>';
    } else {
      md.profiles.forEach(profile => {
        const isDefault = md.defaultId === profile.id;
        const isGlobal = storage.globalProfileId === profile.id;
        const isActive = !!profile._active;
        list.appendChild(buildProfileItemV2(profile, modelKey, isDefault, isGlobal, isActive, storage));
      });
    }
    mbody.appendChild(list);

    // Edit panel
    if (editingTarget === 'profile' && currentEditModel === modelKey) {
      if (editingId === '__new__') {
        mbody.appendChild(buildEditPanel(null, false, storage, modelKey));
      } else {
        const existing = md.profiles.find(p => p.id === editingId);
        if (existing) mbody.appendChild(buildEditPanel(existing, false, storage, modelKey));
      }
    }

    body.appendChild(section);
  });

  // 大总结区（在四个模型之后）
  const summaryDivider = document.createElement('div');
  summaryDivider.className = 'wx-divider';
  summaryDivider.innerHTML = '<span>📦 大总结预设</span>';
  body.appendChild(summaryDivider);

  renderSummaryInline(body, storage);
}

let currentEditModel = null;

function buildProfileItemV2(profile, modelKey, isDefault, isGlobal, isActive, storage) {
  const div = document.createElement('div');
  div.className = 'wx-profile-item' + (isActive ? ' wx-active-profile' : '');
  div.dataset.id = profile.id;

  const globeClass = storage.autoSwitch ? 'wx-globe-btn wx-globe-disabled' : ('wx-globe-btn' + (isGlobal ? ' wx-globe-active' : ''));

  div.innerHTML = `
    <div class="wx-profile-top">
      <div class="wx-profile-name">${escHtml(profile.name)}</div>
      <div class="wx-profile-meta">${escHtml(profileMeta(profile))}</div>
    </div>
    <div class="wx-profile-actions">
      <button class="${globeClass}" data-action="globe" title="设为全局默认（关闭自动切换后生效）">🌐</button>
      <button class="wx-star-btn ${isDefault ? 'wx-starred' : ''}" data-action="star" title="设为该模型默认">⭐</button>
      <button class="wx-icon-btn" data-action="apply" title="应用">✅</button>
      <button class="wx-icon-btn" data-action="rename" title="重命名">✏️</button>
      <button class="wx-icon-btn" data-action="edit" title="重置条目">🔄</button>
      <button class="wx-icon-btn wx-icon-danger" data-action="delete" title="删除">❌</button>
    </div>
  `;

  // Globe (global default)
  div.querySelector('[data-action="globe"]').addEventListener('click', (e) => {
    e.stopPropagation();
    if (storage.autoSwitch) return;
    storage.globalProfileId = isGlobal ? null : profile.id;
    saveStorage(storage);
    renderBody(storage);
  });

  // Apply
  div.querySelector('[data-action="apply"]').addEventListener('click', async (e) => {
    e.stopPropagation();
    try {
      const res = await applyActivationTree(profile.tree);
      await applyApiParams(profile.apiParams);
      if (!reportApply(res, `已应用：${profile.name}`)) return;
      storage.models[modelKey].profiles.forEach(p => p._active = p.id === profile.id);
      saveStorage(storage);
      renderBody(storage);
    } catch(err) {
      console.error('[美梦巡游] 应用方案失败', err);
      toastr.error('应用方案失败：' + err.message);
    }
  });

  // Rename
  div.querySelector('[data-action="rename"]').addEventListener('click', async (e) => {
    e.stopPropagation();
    const newName = await showInputDialog('重命名预设方案', profile.name, profile.name);
    if (!newName || newName === profile.name) return;
    profile.name = newName;
    saveStorage(storage);
    renderBody(storage);
    toastr.success(`已重命名为「${newName}」`);
  });

  // Edit
  div.querySelector('[data-action="edit"]').addEventListener('click', (e) => {
    e.stopPropagation();
    editingId = profile.id;
    editingTarget = 'profile';
    currentEditModel = modelKey;
    renderBody(storage);
  });

  // Delete
  div.querySelector('[data-action="delete"]').addEventListener('click', (e) => {
    e.stopPropagation();
    if (!confirm(`确认删除预设方案「${profile.name}」？`)) return;
    const md = storage.models[modelKey];
    md.profiles = md.profiles.filter(p => p.id !== profile.id);
    if (md.defaultId === profile.id) md.defaultId = null;
    if (storage.globalProfileId === profile.id) storage.globalProfileId = null;
    saveStorage(storage);
    editingId = null;
    renderBody(storage);
    toastr.success('已删除');
  });

  // Star
  div.querySelector('[data-action="star"]').addEventListener('click', (e) => {
    e.stopPropagation();
    const md = storage.models[modelKey];
    md.defaultId = isDefault ? null : profile.id;
    saveStorage(storage);
    renderBody(storage);
  });

  return div;
}

// 大总结内联渲染（不再是独立tab）
function renderSummaryInline(body, storage) {
  const wrapper = document.createElement('div');
  const profiles = storage.summaryProfiles || [];
  const activeId = storage.activeSummaryId;

  // 工具栏
  const toolbar = document.createElement('div');
  toolbar.className = 'wx-toolbar';
  toolbar.innerHTML = `
    <div class="wx-toolbar-left">
      <button class="wx-btn wx-btn-primary" data-action="summary-new">➕ 新建大总结预设</button>
    </div>
  `;
  toolbar.querySelector('[data-action="summary-new"]').addEventListener('click', () => {
    editingId = '__summary_new__';
    editingTarget = 'summary';
    renderBody(storage);
  });
  wrapper.appendChild(toolbar);

  // 列表
  const list = document.createElement('div');
  list.className = 'wx-profile-list';

  if (profiles.length === 0 && editingTarget !== 'summary') {
    list.innerHTML = '<div class="wx-empty">暂无大总结预设方案</div>';
  } else {
    profiles.forEach(sp => {
      const isActive = sp.id === activeId;
      const item = document.createElement('div');
      item.className = 'wx-profile-item' + (isActive ? ' wx-active-profile' : '');
      item.innerHTML = `
        <div class="wx-profile-top">
          <div class="wx-profile-name">${escHtml(sp.name)}</div>
          <div class="wx-profile-meta">${escHtml(profileMeta(sp))}</div>
        </div>
        <div class="wx-profile-actions">
          <button class="wx-star-btn ${isActive ? 'wx-starred' : ''}" data-action="star" title="设为默认大总结预设">⭐</button>
          <button class="wx-icon-btn" data-action="apply" title="应用">✅</button>
          <button class="wx-icon-btn" data-action="rename" title="重命名">✏️</button>
          <button class="wx-icon-btn" data-action="edit" title="重置条目">🔄</button>
          <button class="wx-icon-btn wx-icon-danger" data-action="delete" title="删除">❌</button>
        </div>
      `;

      // 星标（设为激活）
      item.querySelector('[data-action="star"]').addEventListener('click', (e) => {
        e.stopPropagation();
        storage.activeSummaryId = isActive ? null : sp.id;
        saveStorage(storage);
        renderBody(storage);
      });

      // 应用
      item.querySelector('[data-action="apply"]').addEventListener('click', async (e) => {
        e.stopPropagation();
        try {
          const res = await applyActivationTree(sp.tree);
          if (!reportApply(res, `已应用大总结预设：${sp.name}`)) return;
          storage.activeSummaryId = sp.id;
          saveStorage(storage);
          renderBody(storage);
        } catch(err) {
          console.error('[美梦巡游] 应用大总结预设失败', err);
          toastr.error('应用大总结预设失败：' + err.message);
        }
      });

      // 重命名
      item.querySelector('[data-action="rename"]').addEventListener('click', async (e) => {
        e.stopPropagation();
        const newName = await showInputDialog('重命名大总结预设', sp.name, sp.name);
        if (!newName || newName === sp.name) return;
        sp.name = newName;
        saveStorage(storage);
        renderBody(storage);
        toastr.success(`已重命名为「${newName}」`);
      });

      // 编辑
      item.querySelector('[data-action="edit"]').addEventListener('click', (e) => {
        e.stopPropagation();
        editingId = sp.id;
        editingTarget = 'summary';
        renderBody(storage);
      });

      // 删除
      item.querySelector('[data-action="delete"]').addEventListener('click', (e) => {
        e.stopPropagation();
        if (!confirm(`确认删除大总结预设「${sp.name}」？`)) return;
        storage.summaryProfiles = storage.summaryProfiles.filter(x => x.id !== sp.id);
        if (storage.activeSummaryId === sp.id) storage.activeSummaryId = null;
        saveStorage(storage);
        editingId = null;
        renderBody(storage);
        toastr.success('已删除');
      });

      list.appendChild(item);
    });
  }
  wrapper.appendChild(list);

  // 编辑面板
  if (editingTarget === 'summary') {
    if (editingId === '__summary_new__') {
      wrapper.appendChild(buildEditPanel(null, true, storage, null));
    } else {
      const existing = profiles.find(p => p.id === editingId);
      if (existing) wrapper.appendChild(buildEditPanel(existing, true, storage, null));
    }
  }

  body.appendChild(wrapper);
}

