    <div class="wx-footer" style="padding:10px 0 0; border-top:none;">
      <button class="wx-btn wx-btn-primary" id="wx-s-save">保存设置</button>
    </div>
    <div class="wx-settings-section" style="margin-top:14px;">
      <div class="wx-settings-title">📦 手动捕捉总结入世界书（兜底）</div>
      <div class="wx-form-row">
        <label class="wx-label">大总结下方按钮没出现/点了没成功时，用这里把聊天里最新一条大总结录入世界书（世界书不存在会自动创建）。<br>📌 和首页快捷指令「📦 捕捉总结入世界书」是同一个功能，点哪个都一样。</label>
      </div>
      <button class="wx-btn wx-btn-primary" id="wx-s-capture">📦 捕捉最新大总结并录入世界书</button>
      <div id="wx-s-capture-status" style="margin-top:8px;font-size:.82em;opacity:.85;"></div>
    </div>
    <div class="wx-settings-section" style="margin-top:14px;">
      <div class="wx-settings-title">🔍 记忆诊断 & 标签清理</div>
      <div class="wx-form-row">
        <label class="wx-label">扫描当前聊天中所有消息的 recall/fold 标签状态，并估算 Token</label>
      </div>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button class="wx-btn wx-btn-primary" id="wx-s-diagnose">📊 扫描诊断</button>
        <button class="wx-btn wx-btn-danger" id="wx-s-clear-tags">🧹 一键清除所有 recall/fold 标签</button>
      </div>
      <div id="wx-s-diag-result" style="margin-top:10px; font-size:.82em; color:var(--wx-text,#d8d4e8); line-height:1.7; display:none;"></div>
    </div>
  `;

  // 自动提醒开关
  div.querySelector('#wx-remind-toggle').addEventListener('click', () => {
    storage.archiveAutoRemind = !storage.archiveAutoRemind;
    div.querySelector('#wx-remind-toggle').classList.toggle('wx-on', storage.archiveAutoRemind);
    saveStorage(storage);
    toastr.info(storage.archiveAutoRemind ? '🔔 已开启自动大总结提醒' : '🔕 已关闭自动大总结提醒');
  });

  // 手动捕捉总结入世界书（兜底）
  const capBtnEl = div.querySelector('#wx-s-capture');
  if (capBtnEl) capBtnEl.addEventListener('click', () => manualCaptureArchive(div.querySelector('#wx-s-capture-status')));

  // 阈值模式切换
  div.querySelectorAll('.wx-option-btn[data-mode]').forEach(btn => {
    btn.addEventListener('click', () => {
      const mode = btn.dataset.mode;
      storage.archiveThresholdMode = mode;
      div.querySelectorAll('.wx-option-btn[data-mode]').forEach(b => b.classList.remove('wx-selected'));
      btn.classList.add('wx-selected');
      div.querySelector('#wx-s-token-row').style.display = mode === 'token' ? 'block' : 'none';
      div.querySelector('#wx-s-floor-row').style.display = mode === 'floor' ? 'block' : 'none';
      saveStorage(storage);
    });
  });

  div.querySelector('#wx-s-save').addEventListener('click', () => {
    storage.archiveThresholdMode = storage.archiveThresholdMode || 'floor';
    storage.archiveToken  = parseInt(div.querySelector('#wx-s-token').value) || 80000;
    storage.archiveFloor  = parseInt(div.querySelector('#wx-s-floor').value) || 100;
    storage.archiveKeepFloors = parseInt(div.querySelector('#wx-s-keep-floors').value) || 5;
    storage.archivePromptRequire = div.querySelector('#wx-s-prompt-require').value;
    storage.archivePromptFormat  = div.querySelector('#wx-s-prompt-format').value;
    storage.archiveCompressRequire = div.querySelector('#wx-s-prompt-compress').value;
    saveStorage(storage);
    toastr.success('设置已保存');
  });

  // 诊断按钮
  div.querySelector('#wx-s-diagnose').addEventListener('click', () => {
    try {
      const ctx = window.SillyTavern.getContext();
      if (!ctx || !ctx.chat) { toastr.warning('无法获取聊天上下文'); return; }
      const history = ctx.chat;
      const total = history.length;

      let foldCount = 0, recallCount = 0, protectedCount = 0, emptyCount = 0, hiddenCount = 0;
      let totalChars = 0, foldChars = 0, recallChars = 0, protectedChars = 0;

      // 记忆系统的 protectCount（配置存在主页面 window / localStorage）
      let memCfg = parentWin['__memoryConfig__'];
      if (!memCfg) { try { memCfg = JSON.parse(parentWin.localStorage.getItem('wx_memory_config') || '{}'); } catch(_) { memCfg = {}; } }
      const protectN = memCfg.protectCount || 20;

      for (let i = 0; i < total; i++) {
        const msg = history[i];
        if (msg.is_system) { hiddenCount++; continue; } // /hide 隐藏楼层不发送，排除出估算
        if (!msg.mes) { emptyCount++; continue; }
        const mes = msg.mes;
        const chars = mes.length;
        totalChars += chars;

        if (i >= total - protectN) {
          protectedCount++;
          protectedChars += chars;
        } else if (mes.indexOf('<span data-rag="recall"') === 0) {
          recallCount++;
          recallChars += chars;
        } else if (mes.indexOf('<span data-rag="fold"') === 0) {
          foldCount++;
          foldChars += chars;
        } else {
          protectedCount++;
          protectedChars += chars;
        }
      }

      // 估算 Token: 中文约 1.5 字/token，英文约 4 字符/token，混合取 ~2 字符/token
      const estTokenAll = Math.round(totalChars / 2);
      const estTokenProtected = Math.round(protectedChars / 2);
      const estTokenRecall = Math.round(recallChars / 2);
      const estTokenFold = Math.round(foldChars / 2);

      // 估算 fold 消息只发 synopsis 时的 token（synopsis 大约占原文 15-25%）
      const estFoldSynopsisTokens = Math.round(estTokenFold * 0.2);

      // 记忆系统开启时的实际发送量 ≈ 保护层(全文) + recall(全文) + fold(仅synopsis)
      const estWithMemory = estTokenProtected + estTokenRecall + estFoldSynopsisTokens;
      // 记忆系统关闭时 = 全部原文
      const estWithoutMemory = estTokenAll;

      const resultEl = div.querySelector('#wx-s-diag-result');
      resultEl.style.display = 'block';
      resultEl.innerHTML = `
        <div style="border:1px solid var(--wx-border,rgba(140,130,200,.2)); border-radius:8px; padding:12px; background:rgba(0,0,0,.15);">
          <div style="font-weight:600; margin-bottom:8px;">📊 诊断结果</div>
          <div>📌 总楼层：<b>${total}</b>（空消息 ${emptyCount}）</div>
          <div>🙈 已隐藏楼层（/hide，不发送）：<b>${hiddenCount}</b> 条（已从下列估算中排除）</div>
          <div>🛡️ 保护层（最近 ${protectN} 层，全文发送）：<b>${protectedCount}</b> 条 ≈ <b>${estTokenProtected.toLocaleString()}</b> tokens</div>
          <div>🔁 Recall 标签（全文+召回流）：<b>${recallCount}</b> 条 ≈ <b>${estTokenRecall.toLocaleString()}</b> tokens</div>
          <div>📦 Fold 标签（仅发 Synopsis）：<b>${foldCount}</b> 条，原文 ≈ <b>${estTokenFold.toLocaleString()}</b> tokens，Synopsis ≈ <b>${estFoldSynopsisTokens.toLocaleString()}</b> tokens</div>
          <hr style="border-color:var(--wx-border,rgba(140,130,200,.2)); margin:8px 0;">
          <div>✅ <b>记忆系统开启时</b>估算：≈ <b style="color:#48bb78;">${estWithMemory.toLocaleString()}</b> tokens</div>
          <div>⚠️ <b>记忆系统关闭时</b>估算：≈ <b style="color:#f56565;">${estWithoutMemory.toLocaleString()}</b> tokens</div>
          <div style="margin-top:6px; font-size:.9em; opacity:.7;">（Token 估算基于中英混合 ≈ 2字符/token，仅供参考）</div>
        </div>
      `;
    } catch(e) {
      toastr.error('诊断失败：' + e.message);
      console.error('[美梦助手] 诊断错误', e);
    }
  });

  // 清除标签按钮
  div.querySelector('#wx-s-clear-tags').addEventListener('click', () => {
    if (!confirm('⚠️ 确认清除所有消息的 recall/fold 标签？\\n\\n清除后所有消息将变为完整正文（无压缩），下次记忆系统运行时会重新标记。')) return;
    try {
      const ctx = window.SillyTavern.getContext();
      if (!ctx || !ctx.chat) { toastr.warning('无法获取聊天上下文'); return; }
      const history = ctx.chat;
      let cleared = 0;
      for (let i = 0; i < history.length; i++) {
        const msg = history[i];
        if (!msg.mes) continue;
        const orig = msg.mes;
        msg.mes = msg.mes
          .replace(/^<span data-rag="fold"[^>]*><\/span>/, '')
          .replace(/^<span data-rag="recall"[^>]*><\/span>/, '');
        if (msg.mes !== orig) cleared++;
      }
      toastr.success('已清除 ' + cleared + ' 条消息的标签');
      // 重新运行诊断
      div.querySelector('#wx-s-diagnose').click();
    } catch(e) {
      toastr.error('清除失败：' + e.message);
      console.error('[美梦助手] 清除标签错误', e);
    }
  });

  body.appendChild(div);
}

