        quickCommandEdits: s.quickCommandEdits || {},
        quickCommandCustom: s.quickCommandCustom || [],
        archivePromptRequire: s.archivePromptRequire || '',
        archivePromptFormat: s.archivePromptFormat || '',
        archiveCompressRequire: s.archiveCompressRequire || '',
        archiveToken: s.archiveToken,
        archiveFloor: s.archiveFloor,
        archiveKeepFloors: s.archiveKeepFloors,
        archiveThresholdMode: s.archiveThresholdMode,
        archiveAutoRemind: s.archiveAutoRemind,
        models: s.models || {},
        summaryProfiles: s.summaryProfiles || [],
        activeSummaryId: s.activeSummaryId || null,
        theme: s.theme || 'night',
      };
      const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = '美梦巡游_用户配置_' + new Date().toLocaleDateString('zh-CN').replace(/\//g, '-') + '.json';
      a.click();
      URL.revokeObjectURL(url);
      const statusEl = div.querySelector('#wx-s-export-import-status');
      if (statusEl) statusEl.textContent = '✅ 配置已导出';
    } catch(e) {
      toastr.error('导出失败：' + e.message);
    }
  });

  // 导入配置
  div.querySelector('#wx-s-import-config').addEventListener('change', (evt) => {
    const file = evt.target.files[0];
