      try {
        const imported = JSON.parse(e.target.result);
        if (!imported._exportVersion) {
          toastr.error('无效的配置文件：缺少版本标识');
          return;
        }
        const s = loadStorage();
        let count = 0;
        // 快捷指令
        if (imported.quickCommandEdits && typeof imported.quickCommandEdits === 'object') {
          s.quickCommandEdits = imported.quickCommandEdits; count++;
