        if (imported.archiveFloor != null) s.archiveFloor = imported.archiveFloor;
        if (imported.archiveKeepFloors != null) s.archiveKeepFloors = imported.archiveKeepFloors;
        if (imported.archiveThresholdMode) s.archiveThresholdMode = imported.archiveThresholdMode;
        if (imported.archiveAutoRemind != null) s.archiveAutoRemind = imported.archiveAutoRemind;
        // 预设方案
        if (imported.models && typeof imported.models === 'object') {
          s.models = imported.models; count++;
        }
        if (Array.isArray(imported.summaryProfiles)) {
          s.summaryProfiles = imported.summaryProfiles; count++;
        }
        if (imported.activeSummaryId !== undefined) {
          s.activeSummaryId = imported.activeSummaryId;
        }
        if (imported.theme) s.theme = imported.theme;
        saveStorage(s);
        const statusEl = div.querySelector('#wx-s-export-import-status');
        if (statusEl) statusEl.innerHTML = '✅ 已导入 ' + count + ' 类配置（来自 ' + (imported._presetVersion || '未知版本') + '，导出于 ' + (imported._exportDate ? new Date(imported._exportDate).toLocaleString('zh-CN') : '未知') + '）<br>⚠️ 请刷新页面以使导入生效。';
        toastr.success('配置导入成功，请刷新页面');
      } catch(err) {
        toastr.error('导入失败：' + err.message);
      }
    };
    reader.readAsText(file);
    evt.target.value = '';
  });

  body.appendChild(div);
}

// ── 面板构建 ─────────────────────────────────────────────────
function buildPanel() {
  const overlay = document.createElement('div');
  overlay.id = 'wx-overlay';

  overlay.innerHTML = `
    <div id="wx-panel">
      <div class="wx-header">
        <span class="wx-header-title">🦋 美梦巡游 ${WX_VERSION} 🍻</span>
        <div style="display:flex;align-items:center;">
          <button class="wx-theme-toggle" id="wx-theme-toggle" title="切换日/夜模式">🌗</button>
          <button class="wx-close" id="wx-close">✕</button>
        </div>
      </div>
      <div class="wx-tabs" id="wx-tabs">
        <button class="wx-tab" data-tab="quick">快捷指令</button>
        <button class="wx-tab" data-tab="config">预设切换配置</button>
        <button class="wx-tab" data-tab="settings">自动大总结设置</button>
        <button class="wx-tab" data-tab="io">配置导入导出</button>
      </div>
      <div class="wx-body" id="wx-body"></div>
    </div>
  `;

  // 直接用原生 appendChild 挂载到主页面 body，确保手机端正确渲染
  document.body.appendChild(overlay);
  panelEl = overlay;

  // 关闭
  overlay.querySelector('#wx-close').addEventListener('click', hidePanel);
  overlay.addEventListener('click', e => { if (e.target === overlay) hidePanel(); });

  // 日/夜主题切换
  overlay.querySelector('#wx-theme-toggle').addEventListener('click', () => {
    const s = loadStorage();
    s.theme = s.theme === 'day' ? 'night' : 'day';
    saveStorage(s);
    applyTheme(s.theme);
  });

  // 分页切换
  overlay.querySelectorAll('.wx-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      currentTab = tab.dataset.tab;
      editingId = null;
      editingTarget = null;
      renderBody(loadStorage());
    });
  });

  return overlay;
}

function applyTheme(theme) {
  const panel = document.getElementById('wx-panel');
  if (!panel) return;
  if (theme === 'day') panel.classList.add('wx-day');
  else panel.classList.remove('wx-day');
  const btn = document.getElementById('wx-theme-toggle');
  if (btn) btn.textContent = theme === 'day' ? '☀️' : '🌙';
}

function showPanel() {
  injectStyle();
  if (!panelEl) buildPanel();
  const storage = loadStorage();
  if (!currentTab) currentTab = 'quick';
  editingId = null;
  editingTarget = null;
  applyTheme(storage.theme || 'night');
  renderBody(storage);
  requestAnimationFrame(() => panelEl.classList.add('wx-visible'));
}

function hidePanel() {
  if (!panelEl) return;
  panelEl.classList.remove('wx-visible');
}

function isPanelVisible() {
  return panelEl && panelEl.classList.contains('wx-visible');
}

// ── 工具函数 ─────────────────────────────────────────────────
function escHtml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// ══════════════════════════════════════════════════════════════
// ── 自动总结核心模块 ─────────────────────────────────────────
// ══════════════════════════════════════════════════════════════

const ARCHIVE_WB_NAME = '美梦记忆_Archive';

// ── 状态机 ───────────────────────────────────────────────────
// archiveState: null | 'prompted' | 'editing' | 'generating' | 'done'
let archiveState = null;
let archiveGeneratingTime = 0; // 进入 generating 状态的时间戳
let archiveSnapshot = null;     // 激活树快照 (用于恢复)

// ── 辅助：获取角色名和聊天ID ─────────────────────────────────
function getCharName() {
  try { return getCurrentCharacterName() || ''; } catch(e) {
    try { const ctx = window.SillyTavern.getContext(); return ctx?.name2 || ''; } catch(e2) { return ''; }
  }
}

function getChatId() {
  try {
    const ctx = window.SillyTavern.getContext();
    return ctx?.getCurrentChatId?.() || ctx?.chatId || '';
  } catch(e) { return ''; }
}

// ── 阈值检测 ─────────────────────────────────────────────────
function checkThreshold() {
  if (archiveState) return;
  const storage = loadStorage();
  if (!storage.archiveAutoRemind) return; // 用户关闭了自动提醒
  const ctx = window.SillyTavern.getContext();
  if (!ctx || !ctx.chat) return;

  const floorCount = ctx.chat.length;

  // 计算 token 估算 (中英混合 ~2字符/token)
  let totalChars = 0;
  for (const msg of ctx.chat) {
    if (msg.is_system) continue; // 补充①：跳过已隐藏(/hide)的楼层，隐藏后不再计入阈值
    if (msg.mes) totalChars += msg.mes.length;
  }
  const estTokens = Math.round(totalChars / 2);

  // 阈值"桶"逻辑：每跨过一个完整阈值就触发一次（100→200→300 / 20w→40w→60w）
  const mode = storage.archiveThresholdMode || 'floor'; // 'floor' | 'token'
  let bucket = 0;
  if (mode === 'token' && storage.archiveToken > 0) {
    bucket = Math.floor(estTokens / storage.archiveToken);
  } else if (mode === 'floor' && storage.archiveFloor > 0) {
    bucket = Math.floor(floorCount / storage.archiveFloor);
  }
  if (bucket < 1) return; // 还没到第一个阈值

  // 已处理桶号持久化到脚本变量，跨刷新/换API/重载iframe都不丢（修"稍后再说后随机重现"）
  const chatId = getChatId();
  storage.archiveHandledBucket = storage.archiveHandledBucket || {};
  const handledKey = chatId + '_' + mode;
  const handled = storage.archiveHandledBucket[handledKey] || 0;
  if (bucket < handled) { // 用户删楼/隐藏导致回退，跟随下调，避免卡死
    storage.archiveHandledBucket[handledKey] = bucket;
    saveStorage(storage);
    return;
  }
  if (bucket <= handled) return; // 这个阈值桶已提示/归档过，不再弹

  showArchivePrompt(storage, floorCount, estTokens, handledKey, bucket);
}

// ── 归档提示条（内联在最新消息底部，不打断沉浸感） ─────────────
function showArchivePrompt(storage, floors, tokens, handledKey, bucket) {
  // 移除旧提示条
  document.querySelectorAll('.wx-archive-hint').forEach(el => el.remove());

  const mode = storage.archiveThresholdMode || 'floor';
  const info = mode === 'token'
    ? `当前上下文 ≈ ${tokens.toLocaleString()} tokens（阈值 ${storage.archiveToken.toLocaleString()}）`
    : `第 ${floors} 楼 · 每 ${storage.archiveFloor} 楼归档`;

  // 找到最新的 AI 消息
  const allMes = document.querySelectorAll('.mes:not([is_user="true"])');
  const lastMes = allMes[allMes.length - 1];
  if (!lastMes) return;
  const mesText = lastMes.querySelector('.mes_text');
  if (!mesText) return;

  const bar = document.createElement('div');
  bar.className = 'wx-archive-hint';
  bar.style.cssText = 'margin-top:14px;padding:12px 14px;border-radius:10px;background:linear-gradient(135deg,rgba(100,80,160,.12),rgba(60,50,120,.08));border:1px solid rgba(140,130,200,.2);';
  bar.innerHTML = `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap;">
      <span style="font-size:.92em;font-weight:600;color:#c4b5fd;">💡 记忆归档提醒</span>
      <span style="font-size:.78em;color:#9590b0;">${info}</span>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">
      <button class="wx-hint-yes" style="padding:6px 16px;border-radius:7px;border:none;background:#a78bfa;color:#fff;font-size:.82em;font-weight:600;cursor:pointer;">📜 开始归档</button>
      <button class="wx-hint-no" style="padding:6px 16px;border-radius:7px;border:1px solid rgba(140,130,200,.25);background:transparent;color:#9590b0;font-size:.82em;cursor:pointer;">稍后再说</button>
    </div>
  `;

  mesText.appendChild(bar);

  // 滚动到提示条可见
  bar.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

  bar.querySelector('.wx-hint-no').addEventListener('click', () => {
    const s = loadStorage();
    s.archiveHandledBucket = s.archiveHandledBucket || {};
    s.archiveHandledBucket[handledKey] = bucket; // 持久记住这个桶已忽略，刷新也不再弹
    saveStorage(s);
    bar.remove();
  });

  bar.querySelector('.wx-hint-yes').addEventListener('click', async () => {
    bar.remove();
    await startArchiveFlow(storage);
  });
}

// ── 总结执行主流程 ───────────────────────────────────────────
async function startArchiveFlow(storage) {
  try {
    archiveState = 'prompted';

    // 1. 状态快照：记录当前所有 prompt 条目的激活状态（同时存入 storage 持久化）
    archiveSnapshot = captureActivationTree();
    if (!archiveSnapshot.length) {
      // 快照抓不到就中止:切过去会回不来,宁可不切
      toastr.error('[美梦巡游·归档] 读取当前预设状态失败，归档中止（避免切换后无法恢复）。请截图控制台报错反馈');
      archiveState = null;
      archiveSnapshot = null;
      return;
    }
    const snapStorage = loadStorage();
    snapStorage._archiveSnapshot = archiveSnapshot;
    saveStorage(snapStorage);
    console.log('[美梦巡游·归档] 快照已保存, 条目数:', archiveSnapshot.length);

    // 2. 检查是否有大总结预设方案
    const summaryProfiles = storage.summaryProfiles || [];
    const activeProfile = summaryProfiles.find(p => p.id === storage.activeSummaryId);
    if (!activeProfile) {
      toastr.warning('⚠️ 未设置大总结预设方案，请先在「预设切换配置」中创建并星标一个大总结预设');
      archiveState = null;
      archiveSnapshot = null;
      return;
    }

    // 3. 切换到大总结预设(切换失败就中止流程,不再假装成功往下走)
    const res = await applyActivationTree(activeProfile.tree);
    if (!reportApply(res, '📦 已切换至大总结预设：' + activeProfile.name)) {
      await restoreFromSnapshot();
      return;
    }

    // 4. 打开 Story_Archive 编辑器
    archiveState = 'editing';
    showArchiveEditor(storage);

  } catch(e) {
    console.error('[美梦巡游·归档] 启动失败', e);
    toastr.error('归档启动失败：' + e.message);
    await restoreFromSnapshot();
  }
}

// ── Story_Archive 编辑器 ─────────────────────────────────────
function showArchiveEditor(storage) {
  // 从当前聊天中提取已有的 Story_Archive 内容
  const ctx = window.SillyTavern.getContext();
  let existingArchive = '';
  if (ctx && ctx.chat) {
    for (const msg of ctx.chat) {
      if (!msg.mes) continue;
      const m = msg.mes.match(/<Story_Archive[^>]*>([\s\S]*?)<\/Story_Archive>/i);
      if (m) { existingArchive = m[1].trim(); break; }
    }
  }

  // 也检查世界书里的已有归档
  if (!existingArchive) {
    try {
      const charName = getCharName();
