        try {
          const entries = await getLorebookEntries(ARCHIVE_WB_NAME);
          const existing = entries.find(e => e.comment === entryKey);
          if (existing && existing.content) {
            const ta = document.getElementById('wx-archive-textarea');
            if (ta && !ta.value.trim()) {
