        <div style="margin-bottom:12px;">
          <label style="font-size:.82em;color:var(--wx-text2,#9590b0);display:block;margin-bottom:4px;">📋 总结模式</label>
          <div style="display:flex;gap:8px;">
            <button type="button" id="wx-ae-mode-append" data-mode="append" style="flex:1;padding:8px;border-radius:7px;border:1px solid rgba(140,130,200,.3);background:#a78bfa;color:#fff;font-size:.82em;cursor:pointer;">🔄 增量总结</button>
            <button type="button" id="wx-ae-mode-compress" data-mode="compress" style="flex:1;padding:8px;border-radius:7px;border:1px solid rgba(140,130,200,.3);background:transparent;color:#9590b0;font-size:.82em;cursor:pointer;">🗜️ 压缩总结</button>
          </div>
          <div id="wx-ae-mode-desc" style="font-size:.76em;color:#9590b0;margin-top:6px;line-height:1.5;">只总结新楼层，追加到已有归档后面。楼层不多时用这个。</div>
        </div>
        <div style="margin-bottom:12px;">
          <label style="font-size:.82em;color:var(--wx-text2,#9590b0);display:block;margin-bottom:4px;">🎯 使用大总结预设</label>
          <select id="wx-ae-preset-select" style="width:100%;padding:6px 10px;border-radius:6px;border:1px solid var(--wx-border,rgba(140,130,200,.2));background:var(--wx-input-bg,rgba(0,0,0,.25));color:var(--wx-text,#d8d4e8);font-size:.85em;">
            ${(storage.summaryProfiles || []).map(p =>
