          以下是已有的归档内容。你可以编辑后发送，外层的 &lt;Story_Archive&gt; 标签由系统自动包裹。<br>
          如果为空，表示这是首次大总结。
        </div>
        <textarea id="wx-archive-textarea" style="width:100%;min-height:200px;max-height:50vh;border-radius:8px;border:1px solid var(--wx-border,rgba(140,130,200,.2));background:rgba(0,0,0,.25);color:var(--wx-text,#d8d4e8);padding:10px;font-size:.88em;resize:vertical;box-sizing:border-box;line-height:1.7;">${escHtml(existingArchive)}</textarea>
        <div style="margin-top:12px;">
          <div style="font-size:.82em;color:var(--wx-text2,#9590b0);margin-bottom:6px;">📋 大总结要求：</div>
          <textarea id="wx-archive-prompt-require-edit" style="width:100%;min-height:60px;border-radius:8px;border:1px solid var(--wx-border,rgba(140,130,200,.2));background:rgba(0,0,0,.25);color:var(--wx-text,#d8d4e8);padding:10px;font-size:.85em;resize:vertical;box-sizing:border-box;line-height:1.6;">${escHtml(storage.archivePromptRequire)}</textarea>
        </div>
        <div style="margin-top:10px;">
          <div style="font-size:.82em;color:var(--wx-text2,#9590b0);margin-bottom:6px;">📐 输出格式模板（标签自动包裹）：</div>
          <div style="border:1px solid rgba(140,130,200,.25);border-radius:8px;overflow:hidden;background:rgba(140,130,200,.04);">
            <div style="padding:4px 10px;font-size:.72em;font-family:monospace;color:#a78bfa;opacity:.7;border-bottom:1px dashed rgba(140,130,200,.15);user-select:none;">&lt;Story_Archive type="global_history" status="read_only"&gt;</div>
            <textarea id="wx-archive-prompt-format-edit" style="width:100%;min-height:80px;border:none;border-radius:0;background:rgba(0,0,0,.25);color:var(--wx-text,#d8d4e8);padding:10px;font-size:.85em;resize:vertical;box-sizing:border-box;line-height:1.6;">${escHtml(storage.archivePromptFormat)}</textarea>
            <div style="padding:4px 10px;font-size:.72em;font-family:monospace;color:#a78bfa;opacity:.7;border-top:1px dashed rgba(140,130,200,.15);user-select:none;">&lt;/Story_Archive&gt;</div>
          </div>
        </div>
      </div>
      <div style="padding:12px 18px;border-top:1px solid var(--wx-border,rgba(140,130,200,.2));display:flex;justify-content:flex-end;gap:8px;background:rgba(0,0,0,.1);">
        <button class="wx-btn" id="wx-ae-cancel">取消（恢复预设）</button>
        <button class="wx-btn wx-btn-primary" id="wx-ae-send">🚀 发送大总结请求</button>
      </div>
    </div>
  `;

  document.body.appendChild(overlay);

  // 总结模式切换（增量 append / 压缩 compress）
  let editorMode = 'append';
  const modeAppendBtn = overlay.querySelector('#wx-ae-mode-append');
  const modeCompressBtn = overlay.querySelector('#wx-ae-mode-compress');
  const modeDescEl = overlay.querySelector('#wx-ae-mode-desc');
  const requireTaEl = overlay.querySelector('#wx-archive-prompt-require-edit');
  function setEditorMode(m) {
    editorMode = m;
    const isCompress = m === 'compress';
    modeCompressBtn.style.background = isCompress ? '#a78bfa' : 'transparent';
    modeCompressBtn.style.color = isCompress ? '#fff' : '#9590b0';
    modeAppendBtn.style.background = isCompress ? 'transparent' : '#a78bfa';
    modeAppendBtn.style.color = isCompress ? '#9590b0' : '#fff';
    modeDescEl.textContent = isCompress
      ? '把已有归档整体二次压缩，加上新楼层重写成一份完整档，覆盖旧档（覆盖前自动备份到隐藏条目）。楼层很多、归档太长时用这个。'
      : '只总结新楼层，追加到已有归档后面。楼层不多时用这个。';
    if (requireTaEl) requireTaEl.value = isCompress ? (storage.archiveCompressRequire || '') : (storage.archivePromptRequire || '');
  }
  modeAppendBtn.addEventListener('click', () => setEditorMode('append'));
  modeCompressBtn.addEventListener('click', () => setEditorMode('compress'));

  // 预设选择器：切换时即时应用
  const presetSelect = overlay.querySelector('#wx-ae-preset-select');
  if (presetSelect) {
    presetSelect.addEventListener('change', async () => {
      const selectedId = presetSelect.value;
      const profiles = storage.summaryProfiles || [];
      const profile = profiles.find(p => p.id === selectedId);
      if (profile) {
        try {
          const res = await applyActivationTree(profile.tree);
          await applyApiParams(profile.apiParams);
          reportApply(res, '已切换至大总结预设：' + profile.name);
        } catch(err) {
          console.error('[美梦巡游·归档] 切换大总结预设失败', err);
          toastr.error('切换大总结预设失败：' + err.message);
        }
      }
    });
  }

  // 取消 → 恢复预设
  const cancelHandler = async () => {
    overlay.remove();
    const r = await restoreFromSnapshot();
    if (r.ok) toastr.info('已取消归档，预设已恢复');
    else toastr.warning('已取消归档，但预设恢复失败：' + r.detail);
  };
  overlay.querySelector('#wx-ae-close').addEventListener('click', cancelHandler);
  overlay.querySelector('#wx-ae-cancel').addEventListener('click', cancelHandler);

  // 发送
  overlay.querySelector('#wx-ae-send').addEventListener('click', async () => {
