    const formatText = document.getElementById('wx-archive-prompt-format-edit').value.trim();

    // 只发格式模板不发要求是无意义请求，要求为空就拦。
    if (!requireText) { toastr.warning('总结要求为空，请先填写'); return; }

    overlay.remove();
    archiveState = 'generating';
    archiveGeneratingTime = Date.now();
    // 记录本次总结模式，供录入时决定 append/replace（持久化，跨刷新不丢）
    { const _ms = loadStorage(); _ms._archiveMode = editorMode; saveStorage(_ms); }

    // 构造完整消息
    let fullMessage = '';
    // 1. 旧归档内容（如有）
    if (archiveContent) {
      fullMessage += '<Story_Archive type="global_history" status="read_only">\n' + archiveContent + '\n</Story_Archive>\n\n';
    }
    // 2. 总结要求
    if (requireText) {
      fullMessage += requireText + '\n\n';
    }
    // 3. 格式模板（系统包裹标签）
    if (formatText) {
      fullMessage += '3. 输出模板：\n\n```\n<Story_Archive type="global_history" status="read_only">\n' + formatText + '\n</Story_Archive>\n```';
    }

    toastr.info('🚀 正在发送大总结请求...');

    try {
      // /send 写入用户消息，/trigger 触发AI生成回复
      // STScript 用 | 分隔命令。档案正文里的 | （如关系快照的分隔符）会把整条命令从中间切断，
    // 导致只发出第一个 | 之前的内容，总结要求与输出模板全部丢失。必须转义。
    const _escaped = fullMessage.replace(/\|/g, '\\|');
    await triggerSlash('/send ' + _escaped + ' | /trigger');
    } catch(e) {
      console.error('[美梦巡游·归档] 发送失败', e);
      toastr.error('大总结请求发送失败：' + e.message);
      await restoreFromSnapshot();
    }
  });
}

// ── 监听 AI 回复，捕获总结结果 ────────────────────────────────
function onMessageReceived(messageId) {
  if (archiveState !== 'generating') return;

  // 安全超时：如果 generating 状态超过3分钟，视为用户已中途放弃（删消息/取消等），自动重置
  if (Date.now() - archiveGeneratingTime > 3 * 60 * 1000) {
    console.log('[美梦巡游·归档] generating 状态超时（>3min），自动重置');
    archiveState = null;
    archiveGeneratingTime = 0;
    return;
  }

  archiveState = 'done';

  // 在回复消息下方注入"一键录入"按钮
  setTimeout(() => {
    injectArchiveButton(messageId);
  }, 500);
}

function injectArchiveButton(messageId) {
  // 先清除所有旧的 action bar（防止重新生成/多次注入导致重复）
  document.querySelectorAll('.wx-archive-action-bar').forEach(el => el.remove());

  // 找到对应的消息 DOM
  const msgEl = document.querySelector(`.mes[mesid="${messageId}"]`);
  if (!msgEl) {
    console.warn('[美梦巡游·归档] 未找到消息 DOM, mesid:', messageId);
    return;
  }

  const bar = document.createElement('div');
  bar.className = 'wx-archive-action-bar';
  bar.style.cssText = 'display:flex;flex-direction:column;gap:8px;padding:10px 0 4px;align-items:stretch;';
  const keepN = loadStorage().archiveKeepFloors || 5;
  const btnBase = 'padding:8px 14px;border-radius:8px;font-size:.85em;font-weight:500;cursor:pointer;width:100%;text-align:center;';
  bar.innerHTML = `
    <button id="wx-archive-save-${messageId}" style="${btnBase}border:none;background:#a78bfa;color:#fff;">📦 一键录入记忆之书</button>
    <button id="wx-archive-restore-${messageId}" style="${btnBase}border:1px solid rgba(72,187,120,.4);background:rgba(72,187,120,.12);color:#48bb78;">🔄 恢复日常预设</button>
    <button id="wx-archive-keep-${messageId}" style="${btnBase}border:1px solid rgba(247,183,49,.35);background:rgba(247,183,49,.1);color:#f7b731;">🙈 保留最近 ${keepN} 层，其余隐藏</button>
    <span id="wx-archive-status-${messageId}" style="font-size:.8em;opacity:.7;text-align:center;"></span>
  `;

  const mesText = msgEl.querySelector('.mes_text');
  if (mesText) {
    mesText.appendChild(bar);
  }

  // 一键录入
  bar.querySelector(`#wx-archive-save-${messageId}`).addEventListener('click', async () => {
    const statusEl = bar.querySelector(`#wx-archive-status-${messageId}`);
    try {
      statusEl.textContent = '⏳ 正在写入世界书...';

      // 获取 AI 回复的文本
      const ctx = window.SillyTavern.getContext();
      const msg = ctx.chat[messageId];
      if (!msg || !msg.mes) { toastr.error('未找到大总结消息'); return; }
      let summaryText = msg.mes;
      // 清理 HTML 标签
      summaryText = summaryText.replace(/<[^>]+>/g, '').trim();

      await writeToArchiveWorldbook(summaryText);

      // 归档完成：记录楼层 + 把当前所有阈值桶标记为已处理，避免归档后立刻又弹同一个桶
      const totalFloors = ctx.chat.length;
      const archiveStorage = loadStorage();
      archiveStorage.lastArchiveFloor = totalFloors;
      archiveStorage.archiveHandledBucket = archiveStorage.archiveHandledBucket || {};
      const aChatId = getChatId();
      if (archiveStorage.archiveFloor > 0)
        archiveStorage.archiveHandledBucket[aChatId + '_floor'] = Math.floor(totalFloors / archiveStorage.archiveFloor);
      if (archiveStorage.archiveToken > 0) {
        let tChars = 0;
        for (const m of ctx.chat) { if (m.is_system) continue; if (m.mes) tChars += m.mes.length; }
        archiveStorage.archiveHandledBucket[aChatId + '_token'] = Math.floor(Math.round(tChars / 2) / archiveStorage.archiveToken);
      }
      saveStorage(archiveStorage);

      statusEl.textContent = '✅ 已录入！';
      statusEl.style.color = '#48bb78';
      toastr.success('📦 大总结已录入「' + ARCHIVE_WB_NAME + '」世界书');
    } catch(e) {
      console.error('[美梦巡游·归档] 世界书写入失败', e);
      statusEl.textContent = '❌ 写入失败：' + e.message;
      statusEl.style.color = '#f56565';
      toastr.error('世界书写入失败：' + e.message);
    }
  });

  // 恢复预设
  bar.querySelector(`#wx-archive-restore-${messageId}`).addEventListener('click', async () => {
    const r = await restoreFromSnapshot();
    if (r.ok) toastr.success('🔄 已恢复日常预设');
    else toastr.error('恢复日常预设失败：' + r.detail);
  });

  // 保留N层，其余隐藏（N 从设置读取）
  bar.querySelector(`#wx-archive-keep-${messageId}`).addEventListener('click', async () => {
    const keepN = loadStorage().archiveKeepFloors || 5;
    const ctx = window.SillyTavern.getContext();
    const totalFloors = ctx.chat.length;
    if (totalFloors <= keepN) { toastr.info('当前楼层数不超过 ' + keepN + '，无需隐藏'); return; }
    const hideTo = totalFloors - keepN - 1;
    await hideFloors(0, hideTo, true);
    toastr.success('已隐藏第 0-' + hideTo + ' 楼，保留最近 ' + keepN + ' 层（可在大总结设置里修改）');
  });
}

// ── 手动捕捉总结入世界书（兜底，不依赖大总结状态机/按钮渲染） ──
async function manualCaptureArchive(statusEl) {
  const setStatus = (t, color) => { if (statusEl) { statusEl.textContent = t; if (color) statusEl.style.color = color; } };
  try {
    const ctx = window.SillyTavern.getContext();
    if (!ctx || !ctx.chat || !ctx.chat.length) { toastr.error('当前没有聊天记录'); return; }
    // 从最新楼层往前找带大总结特征的 AI 消息
    let target = null;
    for (let i = ctx.chat.length - 1; i >= 0; i--) {
      const m = ctx.chat[i];
      if (!m || m.is_user || !m.mes) continue;
      if (/卷宗|档案说明|Story_Archive|时空流变|事件脉络/.test(m.mes)) { target = m; break; }
    }
    if (!target) { setStatus('❌ 没找到大总结内容', '#f56565'); toastr.warning('没找到带「卷宗/档案」等特征的大总结楼层，请确认大总结已生成'); return; }
    let summaryText = target.mes.replace(/<[^>]+>/g, '').trim();
    if (!summaryText) { setStatus('❌ 总结内容为空', '#f56565'); return; }
    setStatus('⏳ 正在写入世界书...');
    await writeToArchiveWorldbook(summaryText);
    setStatus('✅ 已录入「' + ARCHIVE_WB_NAME + '」', '#48bb78');
    toastr.success('📦 已捕捉最新大总结并录入「' + ARCHIVE_WB_NAME + '」世界书');
  } catch (e) {
    console.error('[美梦巡游·归档] 手动捕捉失败', e);
    setStatus('❌ ' + e.message, '#f56565');
    toastr.error('捕捉失败：' + e.message);
  }
}

// ── 世界书写入逻辑 ───────────────────────────────────────────
async function writeToArchiveWorldbook(summaryText) {
  const charName = getCharName();
  const chatId = getChatId();
  const entryKey = charName + '_' + chatId;

  if (!charName || !chatId) {
    throw new Error('无法获取角色名或聊天ID');
  }

  // 读取本次总结模式
  const ms = loadStorage();
  const mode = ms._archiveMode || 'append';
  delete ms._archiveMode;
  saveStorage(ms);

  // 1. 确保世界书存在
  const allBooks = getLorebooks();
  if (!allBooks.includes(ARCHIVE_WB_NAME)) {
    await createLorebook(ARCHIVE_WB_NAME);
    console.log('[美梦巡游·归档] 已创建世界书:', ARCHIVE_WB_NAME);
  }

  // 2. 检查是否已有同名条目
  const entries = await getLorebookEntries(ARCHIVE_WB_NAME);
  const existing = entries.find(e => e.comment === entryKey);

  // 3. 构建新内容
  const wrappedContent = '<Story_Archive type="global_history" status="read_only">\n' + summaryText + '\n</Story_Archive>';

  if (existing) {
    if (mode === 'compress') {
      // ── 压缩模式：备份旧条目 → 整体替换 ──
      const backupKey = '_backup_' + entryKey;
      const existingBackup = entries.find(e => e.comment === backupKey);
      if (existingBackup) {
        await setLorebookEntries(ARCHIVE_WB_NAME, [{
          uid: existingBackup.uid,
          content: existing.content,
          enabled: false,
        }]);
      } else {
        await createLorebookEntries(ARCHIVE_WB_NAME, [{
          comment: backupKey,
          content: existing.content,
          enabled: false,
          type: 'constant',
          position: 'before_author_note',
          keys: [backupKey],
          order: 99,
        }]);
      }
      console.log('[美梦巡游·归档] 已备份旧归档到:', backupKey);
      // 用新的压缩总结整体替换
      await setLorebookEntries(ARCHIVE_WB_NAME, [{
        uid: existing.uid,
        content: wrappedContent,
      }]);
      console.log('[美梦巡游·归档] 压缩模式：已替换归档条目:', entryKey);
      toastr.success('📦 压缩总结已写入，旧归档已自动备份');
    } else {
      // ── 增量模式：追加 ──
      let oldContent = existing.content;
      oldContent = oldContent.replace(/<\/Story_Archive>\s*$/i, '').trimEnd();
      const newPart = '\n\n--- 归档更新 ' + new Date().toLocaleDateString('zh-CN') + ' ---\n' + summaryText + '\n</Story_Archive>';
      const mergedContent = oldContent + newPart;
      await setLorebookEntries(ARCHIVE_WB_NAME, [{
        uid: existing.uid,
        content: mergedContent,
      }]);
      console.log('[美梦巡游·归档] 已合并更新条目:', entryKey, 'uid:', existing.uid);
    }
  } else {
    // 新建条目（两种模式都一样）
    await createLorebookEntries(ARCHIVE_WB_NAME, [{
      comment: entryKey,
      content: wrappedContent,
      enabled: true,
      type: 'constant',
      position: 'before_author_note',
      keys: [entryKey],
      order: 10,
    }]);
    console.log('[美梦巡游·归档] 已新建条目:', entryKey);
  }
}

// ── 快照恢复 ─────────────────────────────────────────────────
async function restoreFromSnapshot() {
  // 优先从内存读快照，没有则从 storage 持久化读取
  // 返回 { ok, detail }:恢复是真做成了还是没做成,调用方按真实结果提示
  let snap = archiveSnapshot;
  if (!snap) {
    const s = loadStorage();
    snap = s._archiveSnapshot || null;
  }
  let ok = false, detail = '';
  if (snap) {
    try {
      const res = await applyActivationTree(snap, { restoreTail: true });
      if (res.matched === 0) {
        detail = '快照里的条目和当前预设对不上（预设可能换过）';
      } else if (res.verified < res.matched) {
        detail = `只恢复了 ${res.verified}/${res.matched} 个条目`;
      } else {
        ok = true;
      }
      console.log('[美梦巡游·归档] 快照恢复结果', res);
    } catch(e) {
      console.error('[美梦巡游·归档] 快照恢复失败', e);
      detail = e.message;
    }
  } else {
    detail = '没有找到可恢复的快照（可能已经恢复过，或归档流程没走到切换那步）';
  }
  // 清除持久化快照
  const cleanStorage = loadStorage();
  delete cleanStorage._archiveSnapshot;
  saveStorage(cleanStorage);
  // 清除 dismiss 标记
  const chatId = getChatId();
  Object.keys(window).forEach(k => {
    if (k.startsWith('archive_dismissed_' + chatId)) delete window[k];
  });
  archiveState = null;
  archiveSnapshot = null;
  archiveGeneratingTime = 0;
  return { ok, detail };
}

// ── 动态跟随：聊天切换时自动启用/禁用对应条目 ─────────────────
async function dynamicFollowOnChatChange() {
  try {
    const allBooks = getLorebooks();
    if (!allBooks.includes(ARCHIVE_WB_NAME)) return; // 世界书不存在，跳过

    const charName = getCharName();
    const chatId = getChatId();
    if (!charName || !chatId) return;

    const currentKey = charName + '_' + chatId;
    const entries = await getLorebookEntries(ARCHIVE_WB_NAME);
    if (entries.length === 0) return;

    // 排他性过滤：只有匹配当前聊天的条目激活，其余全部关闭
    const updates = [];
    for (const entry of entries) {
      const shouldEnable = entry.comment === currentKey;
      if (entry.enabled !== shouldEnable) {
        updates.push({ uid: entry.uid, enabled: shouldEnable });
      }
    }

    if (updates.length > 0) {
      await setLorebookEntries(ARCHIVE_WB_NAME, updates);
      const enabledCount = updates.filter(u => u.enabled).length;
      console.log(`[美梦巡游·归档] 动态跟随：启用 ${enabledCount} 条, 关闭 ${updates.length - enabledCount} 条`);
    }
  } catch(e) {
    console.warn('[美梦巡游·归档] 动态跟随失败', e);
  }
}


