// ── 推理设置：幂等检查（已正确则跳过，否则修正） ──
(function ensureReasoningSettings() {
  setTimeout(() => {
    try {
      const ctx = mctx();
      const pu = ctx && ctx.powerUserSettings;
      if (!pu || !pu.reasoning) return;
      // 手动设成 thinking/think 系标签的,视为有意为之(DS官方尾部需要),不覆盖
      const cur = String(pu.reasoning.prefix || '');
      if (cur === '<thinking>' || cur === '<think>') {
        if (!pu.reasoning.auto_parse) {
          pu.reasoning.auto_parse = true;
          if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
        }
        console.log('[美梦巡游] 检测到 ' + cur + ' 解析设置,保持不动');
        return;
      }
      const want = { prefix: '<parade>', suffix: '</parade>', auto_parse: true };
      let changed = false;
      Object.keys(want).forEach(k => {
        if (pu.reasoning[k] !== want[k]) { pu.reasoning[k] = want[k]; changed = true; }
      });
      if (changed) {
        const jq = mjq();
        jq('#reasoning_prefix').val(want.prefix);
        jq('#reasoning_suffix').val(want.suffix);
        jq('#reasoning_auto_parse').prop('checked', true);
        if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
        console.log('[美梦巡游] 推理设置已修正为 parade');
      } else {
        console.log('[美梦巡游] 推理设置已就绪');
      }
    } catch(e) {
      console.warn('[美梦巡游] 推理设置检查失败', e);
    }
  }, 1500);
})();

